PathwayData.put("data/reading_writing/units/L02U6.json",{"strand":"reading_writing","level":2,"cefr":"A1b","unit":6,"theme":"Busy Days and Time","essential_question":"How do we use our time well?","schema_version":"1.0","core_words":["morning","afternoon","evening","night","today","tomorrow","yesterday","clock","o'clock","early","late","wake up","prayer","week"],"recycled_words":["first","then","finally","and","but","because","school","bus","homework","family","breakfast","Friday","happy"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L02-U6-LS1","title":"Word Power: Busy Days and Time","lesson_type":"vocabulary","objectives":["read and say 14 words about time and daily routines and 2 Tier 2 words (routine, plan)","put time words in order on a day line and a week line","tell the time in hours with o'clock and talk about daily activities"],"objectives_ar":["قراءة ونطق 14 كلمة عن الوقت والروتين اليومي وكلمتين أكاديميتين (routine, plan).","ترتيب كلمات الوقت على خط اليوم وخط الأسبوع.","قول الوقت بالساعات باستخدام o'clock والتحدث عن الأنشطة اليومية."],"success_criteria":["I can read and say the time words.","I can put morning, afternoon, evening and night in order.","I can say what time I do something."],"success_criteria_ar":["أستطيع قراءة كلمات الوقت ونطقها.","أستطيع ترتيب الصباح والظهيرة والمساء والليل.","أستطيع قول متى أفعل شيئًا."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"morning","pos":"noun","ipa":"/ˈmɔrnɪŋ/","definition":"the early part of the day, before 12 o'clock","arabic":"الصباح","example":"I go to school in the morning.","image_id":"IMG-RW-L02-U6-LS1-V01","audio_id":"AUD-RW-L02-U6-LS1-V01","tier":"core"},{"word":"afternoon","pos":"noun","ipa":"/ˌæftərˈnun/","definition":"the part of the day after 12 o'clock and before the evening","arabic":"بعد الظهر","example":"I do my homework in the afternoon.","image_id":"IMG-RW-L02-U6-LS1-V02","audio_id":"AUD-RW-L02-U6-LS1-V02","tier":"core"},{"word":"evening","pos":"noun","ipa":"/ˈivnɪŋ/","definition":"the end of the day, when the sun goes down","arabic":"المساء","example":"We eat dinner in the evening.","image_id":"IMG-RW-L02-U6-LS1-V03","audio_id":"AUD-RW-L02-U6-LS1-V03","tier":"core"},{"word":"night","pos":"noun","ipa":"/naɪt/","definition":"the dark time when we sleep","arabic":"الليل","example":"I sleep at night.","image_id":"IMG-RW-L02-U6-LS1-V04","audio_id":"AUD-RW-L02-U6-LS1-V04","tier":"core"},{"word":"today","pos":"noun / adverb","ipa":"/təˈdeɪ/","definition":"this day","arabic":"اليوم","example":"Today is Monday.","image_id":"IMG-RW-L02-U6-LS1-V05","audio_id":"AUD-RW-L02-U6-LS1-V05","tier":"core"},{"word":"tomorrow","pos":"noun / adverb","ipa":"/təˈmɑroʊ/","definition":"the day after today","arabic":"غدًا","example":"Tomorrow is Tuesday.","image_id":"IMG-RW-L02-U6-LS1-V06","audio_id":"AUD-RW-L02-U6-LS1-V06","tier":"core"},{"word":"yesterday","pos":"noun / adverb","ipa":"/ˈjɛstərdeɪ/","definition":"the day before today","arabic":"أمس","example":"Yesterday was Sunday.","image_id":"IMG-RW-L02-U6-LS1-V07","audio_id":"AUD-RW-L02-U6-LS1-V07","tier":"core"},{"word":"clock","pos":"noun","ipa":"/klɑk/","definition":"a thing that shows the time","arabic":"ساعة (حائط)","example":"The clock is on the wall.","image_id":"IMG-RW-L02-U6-LS1-V08","audio_id":"AUD-RW-L02-U6-LS1-V08","tier":"core"},{"word":"o'clock","pos":"adverb","ipa":"/əˈklɑk/","definition":"a word we use for the exact hour (7 o'clock)","arabic":"تمامًا (للساعة)","example":"School starts at seven o'clock.","image_id":"IMG-RW-L02-U6-LS1-V09","audio_id":"AUD-RW-L02-U6-LS1-V09","tier":"core"},{"word":"early","pos":"adjective / adverb","ipa":"/ˈɝli/","definition":"before the usual time","arabic":"مبكرًا","example":"Grandpa wakes up early.","image_id":"IMG-RW-L02-U6-LS1-V10","audio_id":"AUD-RW-L02-U6-LS1-V10","tier":"core"},{"word":"late","pos":"adjective / adverb","ipa":"/leɪt/","definition":"after the usual time","arabic":"متأخر","example":"Don't be late for the bus!","image_id":"IMG-RW-L02-U6-LS1-V11","audio_id":"AUD-RW-L02-U6-LS1-V11","tier":"core"},{"word":"wake up","pos":"verb","ipa":"/weɪk ʌp/","definition":"to stop sleeping","arabic":"يستيقظ","example":"I wake up at six o'clock.","image_id":"IMG-RW-L02-U6-LS1-V12","audio_id":"AUD-RW-L02-U6-LS1-V12","tier":"core"},{"word":"prayer","pos":"noun","ipa":"/prɛr/","definition":"the time when Muslims pray (five prayers each day)","arabic":"صلاة","example":"We go to the mosque for the evening prayer.","image_id":"IMG-RW-L02-U6-LS1-V13","audio_id":"AUD-RW-L02-U6-LS1-V13","tier":"core"},{"word":"week","pos":"noun","ipa":"/wik/","definition":"seven days","arabic":"أسبوع","example":"There are seven days in a week.","image_id":"IMG-RW-L02-U6-LS1-V14","audio_id":"AUD-RW-L02-U6-LS1-V14","tier":"core"},{"word":"routine","pos":"noun","ipa":"/ruˈtin/","definition":"the things you usually do every day, in the same order","arabic":"روتين","example":"My morning routine is short.","image_id":"IMG-RW-L02-U6-LS1-V15","audio_id":"AUD-RW-L02-U6-LS1-V15","tier":"tier2"},{"word":"plan","pos":"verb / noun","ipa":"/plæn/","definition":"to think about what you will do; what you will do","arabic":"يخطط / خطة","example":"I plan my day after Fajr.","image_id":"IMG-RW-L02-U6-LS1-V16","audio_id":"AUD-RW-L02-U6-LS1-V16","tier":"tier2"}],"explanation":{"text":"Time words tell us **when** something happens. We can put them **in order** on a **day line**: **morning → afternoon → evening → night**.\n\nWe can put days in order too: **yesterday → today → tomorrow**. Seven days make **a week**.\n\nSmall words help: **in** the morning / afternoon / evening, **at** night, **at** seven o'clock, **on** Monday.","examples":["Day line: **morning** (wake up) → **afternoon** (homework) → **evening** (dinner) → **night** (sleep).","**Yesterday** was Sunday. **Today** is Monday. **Tomorrow** is Tuesday.","**in the morning**: *I go to school in the morning.*","**at night**: *The stars shine at night.*","**at seven o'clock**: *The bus comes at seven o'clock.*","**on Friday**: *We visit Grandpa on Friday.*","**early** ↔ **late**: *Grandpa wakes up early. Sami is late for the bus.*","**prayer** times: *Fajr is the first prayer of the day; Isha is the last prayer at night.*","**week**: *Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday.*"],"common_errors":["✗ In night I sleep. → ✓ At night, I sleep. (Say **at night**.)","✗ I wake up 6 o'clock. → ✓ I wake up at six o'clock. (Use **at** before a time.)","✗ in Monday → ✓ on Monday (Use **on** with days.)","✗ Tomorrow was Tuesday. → ✓ Tomorrow is Tuesday. / Yesterday was Sunday. (Tomorrow is the day **after** today.)","✗ It is 7 clock. → ✓ It is seven o'clock. (Say **o'clock**.)","✗ I wake at 6 o'clock up. → ✓ I wake up at six o'clock. (Keep **wake up** together.)","✗ He is lately. → ✓ He is late. (Say **late** (not lately).)"],"arabic":"كلمات الوقت تخبرنا متى يحدث الشيء، ونرتبها على خط اليوم: morning ← afternoon ← evening ← night.\n\nونرتب الأيام: yesterday (أمس) ← today (اليوم) ← tomorrow (غدًا)، وسبعة أيام تساوي أسبوعًا (week).\n\nحروف صغيرة مهمة: in the morning، at night، at seven o'clock، on Monday.\n\nearly (مبكرًا) عكس late (متأخرًا)."},"video":{"script":[{"time":"00:00–00:15","narration":"Tick-tock! Let's follow Sami's busy day!","on_screen":"Busy Days and Time","visual":"A big friendly clock wakes Sami with a smile."},{"time":"00:15–00:55","narration":"Morning, afternoon, evening, night – the day line!","on_screen":"morning → afternoon → evening → night","visual":"The sun moves across the sky on a long day line; Sami does an activity at each stop."},{"time":"00:55–01:25","narration":"Yesterday, today, tomorrow. Seven days make a week!","on_screen":"yesterday · today · tomorrow · week","visual":"Calendar pages flip; a 'today' sticker moves along."},{"time":"01:25–02:00","narration":"Wake up early, not late! The bus comes at seven o'clock.","on_screen":"early ↔ late · wake up · o'clock","visual":"Two Samis: one ready early, one running after the bus."},{"time":"02:00–02:30","narration":"Five prayers mark our day: Fajr, Dhuhr, Asr, Maghrib, Isha.","on_screen":"prayer times on the day line","visual":"Small mosque icons appear along the day line at the right times."},{"time":"02:30–02:45","narration":"Now make YOUR day line!","on_screen":"Your day line!","visual":"Saqr pins picture cards on a day line."}],"captions_ar":["تك تك! لنتابع يوم سامي المزدحم!","الصباح، بعد الظهر، المساء، الليل… خط اليوم!","أمس، اليوم، غدًا. سبعة أيام تساوي أسبوعًا!","استيقظ مبكرًا لا متأخرًا! الحافلة تأتي في السابعة تمامًا.","خمس صلوات تنظّم يومنا: الفجر والظهر والعصر والمغرب والعشاء.","والآن اصنع خط يومك!"],"voice":"Narrator: American English, cheerful female teacher, speed 0.85. Sami: sleepy, then energetic."},"texts":[],"activities":[{"id":"RW-L02-U6-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"The dark time when we sleep is ___.","answer":"night","explanation":"We sleep at night.","explanation_ar":"الليل.","options":["morning","afternoon","night","today"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The day after today is ___.","answer":"tomorrow","explanation":"Tomorrow = after today.","explanation_ar":"غدًا.","options":["yesterday","tomorrow","today","evening"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The day before today is ___.","answer":"yesterday","explanation":"Yesterday = before today.","explanation_ar":"أمس.","options":["tomorrow","week","morning","yesterday"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"There are seven days in a ___.","answer":"week","explanation":"7 days = a week.","explanation_ar":"أسبوع.","options":["clock","prayer","night","week"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A thing on the wall that shows the time is a ___.","answer":"clock","explanation":"A clock shows the time.","explanation_ar":"ساعة.","options":["clock","week","routine","calendar page"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Sami stops sleeping at six. He ___ at six o'clock.","answer":"wakes up","explanation":"Stop sleeping = wake up.","explanation_ar":"يستيقظ.","options":["goes to bed","wakes up","is late","prays at night"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L02-U6-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Put the time words on the day line. Choose.","instructions_ar":"رتّب كلمات الوقت على خط اليوم. اختر.","items":[{"q":"Which part of the day comes right after the morning?","answer":"afternoon","explanation":"morning → afternoon.","explanation_ar":"بعد الظهر.","options":["night","evening","yesterday","afternoon"],"dok":1,"skill":"day line","stage":"guided"},{"q":"Which part of the day comes right before the night?","answer":"evening","explanation":"evening → night.","explanation_ar":"المساء.","options":["morning","evening","afternoon","tomorrow"],"dok":1,"skill":"day line","stage":"guided"},{"q":"Which order is correct on the day line?","answer":"morning, afternoon, evening, night","explanation":"The sun's path through the day.","explanation_ar":"الترتيب الصحيح.","options":["morning, afternoon, evening, night","night, morning, evening, afternoon","evening, morning, night, afternoon","afternoon, night, morning, evening"],"dok":1,"skill":"day line","stage":"guided"},{"q":"Which order is correct for days?","answer":"yesterday, today, tomorrow","explanation":"Past → now → next.","explanation_ar":"أمس، اليوم، غدًا.","options":["tomorrow, today, yesterday","today, yesterday, tomorrow","yesterday, today, tomorrow","tomorrow, yesterday, today"],"dok":2,"skill":"time order","stage":"guided"},{"q":"Which phrase about the moon and stars is correct?","answer":"at night","explanation":"Say at night.","explanation_ar":"at night.","options":["in night","on night","at night","at the night time on"],"dok":2,"skill":"prepositions of time","stage":"guided"},{"q":"Which phrase about the school bus is correct?","answer":"at seven o'clock","explanation":"at + time.","explanation_ar":"at.","options":["at seven o'clock","in seven o'clock","on seven o'clock","at seven clock"],"dok":2,"skill":"prepositions of time","stage":"guided"}]},{"id":"RW-L02-U6-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"My morning ________ is: wake up, wash, get dressed and eat breakfast.","answer":"routine","explanation":"Things you do every day in the same order.","explanation_ar":"روتين.","stage":"freer"},{"q":"Let's ________ our weekend. What will we do on Friday?","answer":"plan","explanation":"Think about what we will do.","explanation_ar":"نخطط.","stage":"freer"},{"q":"Grandpa wakes up ________ for the Fajr prayer.","answer":"early","explanation":"Before the usual time.","explanation_ar":"مبكرًا.","stage":"freer"},{"q":"Hurry! We are ________ for school!","answer":"late","explanation":"After the usual time.","explanation_ar":"متأخرون.","stage":"freer"},{"q":"Fajr is the first ________ of the day.","answer":"prayer","explanation":"A time Muslims pray.","explanation_ar":"صلاة.","stage":"freer"},{"q":"We eat dinner in the ________ when the sun goes down.","answer":"evening","explanation":"End of the day.","explanation_ar":"المساء.","stage":"freer"}]},{"id":"RW-L02-U6-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR day.","instructions_ar":"اكتب عن يومك.","items":[{"q":"What time do you wake up?","answer":"I wake up at six o'clock.","explanation":"at + time + o'clock.","explanation_ar":"at + الوقت.","dok":1,"skill":"time","stage":"production"},{"q":"Write one thing you do in the afternoon.","answer":"In the afternoon, I do my homework.","explanation":"In the afternoon + activity.","explanation_ar":"In the afternoon + نشاط.","dok":1,"skill":"time words","stage":"production"},{"q":"What did you do yesterday? What will you do tomorrow?","answer":"Yesterday, I visited my uncle. Tomorrow, I will play football.","explanation":"Two time words.","explanation_ar":"كلمتا وقت.","dok":3,"skill":"time words","stage":"production"},{"q":"Are you an early bird or a night owl? Why?","answer":"I am an early bird because I like the quiet morning.","explanation":"Opinion + because.","explanation_ar":"رأي + because.","dok":2,"skill":"connect","stage":"production"}]}],"game":{"name":"Clock Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Day-line dash: the app says 'It is seven o'clock in the morning'; the child sets the clock hands and drags the right activity picture onto the day line. Correct = the sun moves forward.","Pairs have one paper clock.","The teacher reads a time card (It is three o'clock in the afternoon).","Pairs set the clock and hold it up.","The first correct pair says what they do at that time (I play football).","Correct clock + sentence = 2 points."],"data":[]},"exit_quiz":[{"q":"Which time word means *this day*?","answer":"today","explanation":"Today = this day.","explanation_ar":"اليوم.","options":["tomorrow","yesterday","today","week"],"dok":1,"skill":"vocabulary"},{"q":"What is the opposite of *early*?","answer":"late","explanation":"early ↔ late.","explanation_ar":"late.","options":["late","night","morning","today"],"dok":1,"skill":"opposites"},{"q":"Which part of the day is first on the day line?","answer":"morning","explanation":"The day starts in the morning.","explanation_ar":"الصباح.","options":["evening","night","afternoon","morning"],"dok":1,"skill":"day line"},{"q":"*My morning routine is short.* *Routine* means ___.","answer":"the things you usually do, in the same order","explanation":"Routine = usual order of things.","explanation_ar":"روتين.","options":["a kind of clock","a holiday","the things you usually do, in the same order","a new game"],"dok":1,"skill":"vocabulary"},{"q":"Which phrase about Friday is correct?","answer":"on Friday","explanation":"on + day.","explanation_ar":"on.","options":["in Friday","on Friday","at Friday","Friday on"],"dok":1,"skill":"prepositions of time"},{"q":"Which sentence about Sami's alarm is correct?","answer":"Sami wakes up at six o'clock.","explanation":"wake up + at + time.","explanation_ar":"صحيحة.","options":["Sami wakes up in six o'clock.","Sami wakes at six o'clock up.","Sami wakes up at six o'clock.","Sami wake up six clock."],"dok":2,"skill":"grammar"},{"q":"Today is Wednesday. What day was yesterday?","answer":"Tuesday","explanation":"The day before Wednesday.","explanation_ar":"الثلاثاء.","options":["Thursday","Tuesday","Friday","Monday"],"dok":2,"skill":"apply"},{"q":"Today is Wednesday. What day is tomorrow?","answer":"Thursday","explanation":"The day after Wednesday.","explanation_ar":"الخميس.","options":["Thursday","Tuesday","Sunday","Saturday"],"dok":2,"skill":"apply"},{"q":"Which prayer is at the very end of the day line, at night?","answer":"Isha","explanation":"Isha is the night prayer.","explanation_ar":"العشاء.","options":["Fajr","Dhuhr","Asr","Isha"],"dok":2,"skill":"apply"},{"q":"Why is a day line helpful?","answer":"It shows the order of times and activities in a day.","explanation":"It organizes time.","explanation_ar":"يُظهر ترتيب أوقات اليوم.","options":["It tells the weather.","It shows the size of things.","It is a kind of game rule.","It shows the order of times and activities in a day."],"dok":3,"skill":"strategy"}],"images":[{"id":"IMG-RW-L02-U6-LS1-V01","prompt":"Picture for the word 'morning': a sunrise over houses"},{"id":"IMG-RW-L02-U6-LS1-V02","prompt":"Picture for the word 'afternoon': a bright sun high in the sky over a playground"},{"id":"IMG-RW-L02-U6-LS1-V03","prompt":"Picture for the word 'evening': a sunset with an orange sky"},{"id":"IMG-RW-L02-U6-LS1-V04","prompt":"Picture for the word 'night': a moon and stars over a quiet house"},{"id":"IMG-RW-L02-U6-LS1-V05","prompt":"Picture for the word 'today': a calendar page with today circled"},{"id":"IMG-RW-L02-U6-LS1-V06","prompt":"Picture for the word 'tomorrow': a calendar with an arrow to the next day"},{"id":"IMG-RW-L02-U6-LS1-V07","prompt":"Picture for the word 'yesterday': a calendar with an arrow to the day before"},{"id":"IMG-RW-L02-U6-LS1-V08","prompt":"Picture for the word 'clock': a round wall clock"},{"id":"IMG-RW-L02-U6-LS1-V09","prompt":"Picture for the word 'o'clock': a clock showing 7:00"},{"id":"IMG-RW-L02-U6-LS1-V10","prompt":"Picture for the word 'early': a rooster at sunrise and a child getting up"},{"id":"IMG-RW-L02-U6-LS1-V11","prompt":"Picture for the word 'late': a child running after a bus"},{"id":"IMG-RW-L02-U6-LS1-V12","prompt":"Picture for the word 'wake up': a child stretching in bed"},{"id":"IMG-RW-L02-U6-LS1-V13","prompt":"Picture for the word 'prayer': a mosque with a crescent at sunset"},{"id":"IMG-RW-L02-U6-LS1-V14","prompt":"Picture for the word 'week': a week calendar with seven boxes"},{"id":"IMG-RW-L02-U6-LS1-V15","prompt":"Picture for the word 'routine': a row of icons: wake up, wash, dress, eat"},{"id":"IMG-RW-L02-U6-LS1-V16","prompt":"Picture for the word 'plan': a child writing a list on a notepad"},{"id":"IMG-RW-L02-U6-LS1-01","prompt":"Sami's day from sunrise to night on a long day line."},{"id":"IMG-RW-L02-U6-LS1-02","prompt":"A day line and a yesterday-today-tomorrow line."},{"id":"IMG-RW-L02-U6-LS1-03","prompt":"One boy is early for the bus and another is late."}],"audio":[{"id":"AUD-RW-L02-U6-LS1-V01","script":"morning. I go to school in the morning."},{"id":"AUD-RW-L02-U6-LS1-V02","script":"afternoon. I do my homework in the afternoon."},{"id":"AUD-RW-L02-U6-LS1-V03","script":"evening. We eat dinner in the evening."},{"id":"AUD-RW-L02-U6-LS1-V04","script":"night. I sleep at night."},{"id":"AUD-RW-L02-U6-LS1-V05","script":"today. Today is Monday."},{"id":"AUD-RW-L02-U6-LS1-V06","script":"tomorrow. Tomorrow is Tuesday."},{"id":"AUD-RW-L02-U6-LS1-V07","script":"yesterday. Yesterday was Sunday."},{"id":"AUD-RW-L02-U6-LS1-V08","script":"clock. The clock is on the wall."},{"id":"AUD-RW-L02-U6-LS1-V09","script":"o'clock. School starts at seven o'clock."},{"id":"AUD-RW-L02-U6-LS1-V10","script":"early. Grandpa wakes up early."},{"id":"AUD-RW-L02-U6-LS1-V11","script":"late. Don't be late for the bus!"},{"id":"AUD-RW-L02-U6-LS1-V12","script":"wake up. I wake up at six o'clock."},{"id":"AUD-RW-L02-U6-LS1-V13","script":"prayer. We go to the mosque for the evening prayer."},{"id":"AUD-RW-L02-U6-LS1-V14","script":"week. There are seven days in a week."},{"id":"AUD-RW-L02-U6-LS1-V15","script":"routine. My morning routine is short."},{"id":"AUD-RW-L02-U6-LS1-V16","script":"plan. I plan my day after Fajr."},{"id":"AUD-RW-L02-U6-LS1-VID","script":"Tick-tock! Let's follow Sami's busy day! Morning, afternoon, evening, night – the day line! Yesterday, today, tomorrow. Seven days make a week! Wake up early, not late! The bus comes at seven o'clock. Five prayers mark our day: Fajr, Dhuhr, Asr, Maghrib, Isha. Now make YOUR day line!"}]},{"id":"RW-L02-U6-LS2","title":"The Late Alarm Clock","lesson_type":"close_reading","objectives":["read a short play of about 130 words and name its parts: characters, scene, lines, stage directions","use stage directions to understand how characters feel and act","read the lines aloud in different voices for each character"],"objectives_ar":["قراءة مسرحية قصيرة من نحو 130 كلمة وتسمية أجزائها: الشخصيات والمشهد والحوار وإرشادات المسرح.","استخدام إرشادات المسرح لفهم مشاعر الشخصيات وتصرفاتها.","قراءة الحوار بصوت مختلف لكل شخصية."],"success_criteria":["I can find the characters and the scene.","I can tell lines from stage directions.","I can read a part with feeling."],"success_criteria_ar":["أستطيع إيجاد الشخصيات والمشهد.","أستطيع التمييز بين الحوار وإرشادات المسرح.","أستطيع قراءة دور بإحساس."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"alarm clock","pos":"noun","ipa":"/əˈlɑrm klɑk/","definition":"a clock that rings to wake you up","arabic":"منبّه","example":"My alarm clock rings at six.","image_id":"IMG-RW-L02-U6-LS2-V01","audio_id":"AUD-RW-L02-U6-LS2-V01","tier":"core"},{"word":"ring","pos":"verb","ipa":"/rɪŋ/","definition":"to make a loud bell sound","arabic":"يرنّ","example":"The alarm clock did not ring.","image_id":"IMG-RW-L02-U6-LS2-V02","audio_id":"AUD-RW-L02-U6-LS2-V02","tier":"core"},{"word":"miss","pos":"verb","ipa":"/mɪs/","definition":"to be too late for something","arabic":"يفوته","example":"I missed the bus.","image_id":"IMG-RW-L02-U6-LS2-V03","audio_id":"AUD-RW-L02-U6-LS2-V03","tier":"core"},{"word":"calendar","pos":"noun","ipa":"/ˈkæləndər/","definition":"a page that shows the days, weeks and months","arabic":"تقويم","example":"Look at the calendar.","image_id":"IMG-RW-L02-U6-LS2-V04","audio_id":"AUD-RW-L02-U6-LS2-V04","tier":"core"},{"word":"silly","pos":"adjective","ipa":"/ˈsɪli/","definition":"funny and not careful","arabic":"مضحك / سخيف","example":"That was a silly mistake!","image_id":"IMG-RW-L02-U6-LS2-V05","audio_id":"AUD-RW-L02-U6-LS2-V05","tier":"core"},{"word":"play","pos":"noun","ipa":"/pleɪ/","definition":"a story that people act out","arabic":"مسرحية","example":"We read a play in class.","image_id":"IMG-RW-L02-U6-LS2-V06","audio_id":"AUD-RW-L02-U6-LS2-V06","tier":"core"},{"word":"character","pos":"noun","ipa":"/ˈkærɪktər/","definition":"a person or animal in a story or play","arabic":"شخصية","example":"Sami is a character in the play.","image_id":"IMG-RW-L02-U6-LS2-V07","audio_id":"AUD-RW-L02-U6-LS2-V07","tier":"core"}],"explanation":{"text":"A **play** is a story that people **act out**. It looks different from a story.\n\nParts of a play: the **characters** (the cast list at the top), the **scene** (where and when), the **lines** (the words each character says, after the name in CAPITALS) and **stage directions** (in brackets – they tell actors what to **do** and **how** to say the line).\n\nRead the stage directions carefully: they show **feelings** and **actions**. Don't read them aloud as lines!","examples":["Characters: **Sami, Mom, Lama**.","Scene: **Sami's bedroom, eight o'clock in the morning**.","A line: **SAMI: Oh no! My alarm clock did not ring!** – Sami says these words.","A stage direction: **(jumping out of bed)** – this tells the actor what to do.","Feeling from a stage direction: **(laughing)** → Lama thinks it is funny.","Feeling from a stage direction: **(smiling)** → Mom knows something Sami does not know!","Action: **(Sami puts on his shirt the wrong way)** → he is in a big hurry.","Twist at the end: **There is no school today!** – it is Friday.","Read it like an actor: worried voice for Sami, kind voice for Mom, giggly voice for Lama."],"common_errors":["✗ Reading '(laughing)' aloud as Lama's words. → ✓ Lama laughs while she says: 'Sami, why are you running?' (Stage directions are **not** spoken.)","✗ Sami say, 'Oh no!' → ✓ Sami says, 'Oh no!' (One person → **says**.)","✗ The alarm clock didn't rang. → ✓ The alarm clock didn't ring. (After **didn't**, use **ring**.)","✗ I miss the bus yesterday. → ✓ I missed the bus yesterday. (Past → **missed**.)","✗ The characters is Sami, Mom and Lama. → ✓ The characters are Sami, Mom and Lama. (Many characters → **are**.)","✗ In friday there is no school. → ✓ On Friday, there is no school. (**On** + day; capital **F**.)"],"arabic":"المسرحية قصة يمثّلها الناس، وشكلها يختلف عن القصة العادية.\n\nأجزاؤها: الشخصيات (في أعلى الصفحة)، والمشهد (أين ومتى)، والحوار (الكلمات بعد اسم الشخصية المكتوب بحروف كبيرة)، وإرشادات المسرح (بين قوسين، وتخبر الممثل ماذا يفعل وكيف يقول الجملة).\n\nاقرأ إرشادات المسرح بعناية لأنها تُظهر المشاعر والأفعال، ولا تقرأها بصوت عالٍ كأنها حوار.\n\nفي المسرحية: ظن سامي أنه تأخر عن المدرسة، ثم اكتشف أن اليوم جمعة!"},"video":{"script":[{"time":"00:00–00:20","narration":"Today we read a play! A play is a story that people act out.","on_screen":"A Play 🎭","visual":"Curtains open on a small stage set as Sami's bedroom."},{"time":"00:20–01:40","narration":"The Late Alarm Clock. Characters: Sami, Mom, Lama…","on_screen":"(play, acted)","visual":"Animated play: the quiet alarm clock, Mom knocking, Sami jumping up, shirt on backward, one shoe, Lama laughing, the calendar showing Friday."},{"time":"01:40–02:10","narration":"Names in capitals tell who speaks. Words in brackets are stage directions – do them, don't say them!","on_screen":"NAME: line   (stage direction)","visual":"A line glows yellow; a bracket glows blue and shows an actor doing the action."},{"time":"02:10–02:35","narration":"Stage directions show feelings: (laughing), (smiling), (reading slowly).","on_screen":"Feelings 😂 🙂 🤔","visual":"Close-ups of Lama laughing, Mom smiling, Sami reading slowly."},{"time":"02:35–02:55","narration":"Now you are the actors! Choose a part and read with feeling.","on_screen":"Act it out!","visual":"Three children with name cards bow on a stage; Saqr claps."}],"captions_ar":["اليوم نقرأ مسرحية! المسرحية قصة يمثّلها الناس.","المنبّه المتأخر. الشخصيات: سامي، أمه، لمى…","الأسماء بحروف كبيرة تخبرنا من يتكلم، والكلمات بين قوسين إرشادات مسرحية: نفعلها ولا نقولها!","إرشادات المسرح تُظهر المشاعر: يضحك، يبتسم، يقرأ ببطء.","والآن أنتم الممثلون! اختر دورًا واقرأ بإحساس."],"voice":"Narrator: American English, warm female teacher, speed 0.85. Sami: panicked, then relieved. Mom: calm and amused. Lama: giggly little girl."},"texts":[{"type":"reading","title":"The Late Alarm Clock","body":"**Characters:** Sami, Mom, Lama (Sami's little sister)\n\n**Scene:** Sami's bedroom. It is eight o'clock in the morning.\n\n*(Sami is sleeping after the dawn prayer. His alarm clock is quiet.)*\n\n**MOM:** *(knocking on the door)* Sami! Wake up! It is eight o'clock!\n\n**SAMI:** *(jumping out of bed)* Oh no! My alarm clock did not ring! I am late for school!\n\n*(Sami puts on his shirt the wrong way and runs to the kitchen with one shoe.)*\n\n**LAMA:** *(laughing)* Sami, why are you running?\n\n**SAMI:** The school bus comes at seven o'clock! I missed it!\n\n**MOM:** *(smiling)* Sami, look at the calendar. What day is today?\n\n**SAMI:** *(reading slowly)* Friday… Oh! There is no school today!\n\n**LAMA:** Silly Sami!\n\n**SAMI:** *(laughing)* Tonight, I will check my alarm clock AND the calendar!","word_count":129,"audio_id":"AUD-RW-L02-U6-LS2-T1","id":"TXT-RW-L02-U6-LS2-1","genre":"drama","role":"main","difficulty":"200L–350L","glossary":[{"word":"ring","definition":"make a loud sound (a bell or an alarm)","arabic":"يرنّ"},{"word":"missed","definition":"was too late for it","arabic":"فاتني"},{"word":"silly","definition":"a little funny and not careful","arabic":"سخيف / مضحك"}]}],"activities":[{"id":"RW-L02-U6-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the play. Choose the answer.","instructions_ar":"اقرأ المسرحية واختر الإجابة.","items":[{"q":"How many characters are in *The Late Alarm Clock*?","answer":"three","explanation":"Sami, Mom, Lama.","explanation_ar":"ثلاث.","options":["three","two","four","five"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"Where does the play begin?","answer":"in Sami's bedroom","explanation":"Scene: Sami's bedroom.","explanation_ar":"في غرفة سامي.","options":["at school","on the bus","in Sami's bedroom","at the mosque"],"dok":1,"skill":"setting","stage":"controlled"},{"q":"What time is it in the scene?","answer":"eight o'clock in the morning","explanation":"Scene line.","explanation_ar":"الثامنة صباحًا.","options":["seven o'clock at night","six o'clock in the evening","twelve o'clock","eight o'clock in the morning"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"What did Sami do before he went back to sleep?","answer":"He prayed the dawn prayer.","explanation":"Stage direction: after the dawn prayer.","explanation_ar":"صلى الفجر.","options":["He ate breakfast.","He prayed the dawn prayer.","He went to school.","He played football."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When does the school bus come, says Sami?","answer":"at seven o'clock","explanation":"SAMI: The school bus comes at seven o'clock!","explanation_ar":"السابعة.","options":["at eight o'clock","at seven o'clock","at nine o'clock","at night"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What day is it?","answer":"Friday","explanation":"SAMI: Friday…","explanation_ar":"الجمعة.","options":["Friday","Sunday","Monday","Thursday"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U6-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Parts of a play. Choose.","instructions_ar":"أجزاء المسرحية: اختر.","items":[{"q":"*(jumping out of bed)* is a ___.","answer":"stage direction","explanation":"Words in brackets = stage direction.","explanation_ar":"إرشاد مسرحي.","options":["stage direction","line","character","title"],"dok":1,"skill":"drama features","stage":"guided"},{"q":"*LAMA: Silly Sami!* Who says these words?","answer":"Lama","explanation":"The name before the line.","explanation_ar":"لمى.","options":["Sami","Mom","the narrator","Lama"],"dok":1,"skill":"drama features","stage":"guided"},{"q":"Where can you find the list of people in the play?","answer":"at the top, after *Characters:*","explanation":"Cast list at the top.","explanation_ar":"في الأعلى.","options":["at the end","in the stage directions only","at the top, after *Characters:*","in the title"],"dok":1,"skill":"drama features","stage":"guided"},{"q":"Which stage direction shows that Mom knows a secret?","answer":"(smiling)","explanation":"She smiles because she knows it is Friday.","explanation_ar":"تبتسم.","options":["(knocking on the door)","(smiling)","(jumping out of bed)","(reading slowly)"],"dok":2,"skill":"inference","stage":"guided"},{"q":"Why does Sami put on his shirt the wrong way?","answer":"He is in a big hurry.","explanation":"He thinks he is late.","explanation_ar":"لأنه مستعجل.","options":["He likes it that way.","Mom tells him to.","It is a new shirt.","He is in a big hurry."],"dok":2,"skill":"inference","stage":"guided"},{"q":"Should you read *(laughing)* aloud when you act the play?","answer":"No, you do it as you say the line.","explanation":"Stage directions are acted, not spoken.","explanation_ar":"لا، تفعله.","options":["Yes, say it loudly.","Yes, but only at the end.","No, you do it as you say the line.","No, you skip the whole line."],"dok":2,"skill":"drama features","stage":"guided"}]},{"id":"RW-L02-U6-LS2-A3","type":"mcq","stage":"freer","instructions":"Freer practice: Think about the play.","instructions_ar":"فكّر في المسرحية.","items":[{"q":"Underline the line that shows Sami's big mistake.","answer":"SAMI: (jumping out of bed) Oh no! My alarm clock did not ring! I am late for school!","explanation":"He thinks it is a school day.","explanation_ar":"يظن أنه يوم دراسي.","evidence":"SAMI: (jumping out of bed) Oh no! My alarm clock did not ring! I am late for school!","text_id":"TXT-RW-L02-U6-LS2-1","dok":2,"skill":"evidence","stage":"freer"},{"q":"How does Sami feel at the BEGINNING?","answer":"worried","explanation":"He thinks he is late.","explanation_ar":"قلق.","options":["calm","sleepy and happy","angry with Lama","worried"],"dok":2,"skill":"character feelings","stage":"freer"},{"q":"How does Sami feel at the END?","answer":"relieved and amused","explanation":"He laughs.","explanation_ar":"مرتاح ويضحك.","options":["relieved and amused","very angry","sad","scared"],"dok":2,"skill":"character feelings","stage":"freer"},{"q":"What will Sami do tonight?","answer":"check his alarm clock and the calendar","explanation":"Last line.","explanation_ar":"يتحقق من المنبه والتقويم.","options":["buy a new bus","check his alarm clock and the calendar","sleep at school","skip the prayer"],"dok":1,"skill":"key details","stage":"freer"}]},{"id":"RW-L02-U6-LS2-A4","type":"open","stage":"production","instructions":"Writing: Write and act.","instructions_ar":"اكتب ومثّل.","items":[{"q":"What is funny about the play?","answer":"Sami runs to school, but it is Friday and there is no school.","explanation":"The twist.","explanation_ar":"المفاجأة.","dok":2,"skill":"author's craft","stage":"production"},{"q":"Write a new line for Lama with a stage direction.","answer":"LAMA: (clapping) Sami, you have one shoe!","explanation":"NAME: (direction) line.","explanation_ar":"الاسم: (إرشاد) حوار.","dok":3,"skill":"drama writing","stage":"production"},{"q":"What can Sami do to wake up on time on school days?","answer":"He can check his alarm clock every night.","explanation":"A solution.","explanation_ar":"حل.","dok":2,"skill":"problem solving","stage":"production"},{"q":"Did something silly ever happen to you in the morning? Write two sentences.","answer":"One morning, I put on two different socks. My brother laughed, and I laughed too!","explanation":"A personal connection.","explanation_ar":"تجربة شخصية.","dok":3,"skill":"connect","stage":"production"}]},{"id":"RW-L02-U6-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Late Alarm Clock\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Late Alarm Clock”.","answer":"129 words","title":"The Late Alarm Clock","body":"**Characters:** Sami, Mom, Lama (Sami's little sister)\n\n**Scene:** Sami's bedroom. It is eight o'clock in the morning.\n\n*(Sami is sleeping after the dawn prayer. His alarm clock is quiet.)*\n\n**MOM:** *(knocking on the door)* Sami! Wake up! It is eight o'clock!\n\n**SAMI:** *(jumping out of bed)* Oh no! My alarm clock did not ring! I am late for school!\n\n*(Sami puts on his shirt the wrong way and runs to the kitchen with one shoe.)*\n\n**LAMA:** *(laughing)* Sami, why are you running?\n\n**SAMI:** The school bus comes at seven o'clock! I missed it!\n\n**MOM:** *(smiling)* Sami, look at the calendar. What day is today?\n\n**SAMI:** *(reading slowly)* Friday… Oh! There is no school today!\n\n**LAMA:** Silly Sami!\n\n**SAMI:** *(laughing)* Tonight, I will check my alarm clock AND the calendar!","words":129,"limit":155}],"time_limit_sec":155}],"game":{"name":"Play Parts Hunt","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Highlighter game: the play appears on screen; the child taps lines (yellow) and stage directions (blue). When all are colored, the characters act the play.","Teams get the play cut into strips.","They sort each strip into a box: Characters, Scene, Line or Stage direction.","Teams put the play back in order.","Each team acts the play; the audience checks that stage directions are acted, not read.","Correct sort = 1 point per strip; great acting = 3 bonus points."],"data":[]},"exit_quiz":[{"q":"*The Late Alarm Clock* is a play. A play is a story that people ___.","answer":"act out","explanation":"Plays are acted.","explanation_ar":"يمثّلونها.","options":["draw","eat","act out","count"],"dok":1,"skill":"genre"},{"q":"In *The Late Alarm Clock*, the words in brackets ( ) are ___.","answer":"stage directions","explanation":"Brackets = stage directions.","explanation_ar":"إرشادات المسرح.","options":["stage directions","lines to say","the title","a list of characters"],"dok":1,"skill":"drama features"},{"q":"Who knocks on Sami's door?","answer":"Mom","explanation":"MOM: (knocking on the door)","explanation_ar":"الأم.","options":["Lama","Grandpa","the bus driver","Mom"],"dok":1,"skill":"characters"},{"q":"*My alarm clock did not ring.* *Ring* means ___.","answer":"make a loud bell sound","explanation":"Ring = make a bell sound.","explanation_ar":"يرنّ.","options":["go to sleep","break into pieces","make a loud bell sound","be quiet"],"dok":1,"skill":"vocabulary"},{"q":"*I missed the bus!* *Missed* means ___.","answer":"was too late for it","explanation":"Miss = be too late.","explanation_ar":"فاتني.","options":["drove it","was too late for it","found it","liked it"],"dok":1,"skill":"vocabulary"},{"q":"Why does Mom ask Sami to look at the calendar?","answer":"to show him it is Friday","explanation":"The calendar shows the day.","explanation_ar":"لتريه أن اليوم جمعة.","options":["to show him the weather","to show him it is Friday","to find his shoe","to tell him the time"],"dok":2,"skill":"inference"},{"q":"Which line is said by Sami?","answer":"\"There is no school today!\"","explanation":"SAMI: …There is no school today!","explanation_ar":"سامي.","options":["\"Silly Sami!\"","\"Sami! Wake up!\"","\"Sami, why are you running?\"","\"There is no school today!\""],"dok":2,"skill":"drama features"},{"q":"How does a play look different from a story?","answer":"It has character names before the lines and stage directions in brackets.","explanation":"Plays use names, lines and brackets.","explanation_ar":"أسماء وحوار وأقواس.","options":["It has character names before the lines and stage directions in brackets.","It has no words.","It has only pictures.","It has headings and captions."],"dok":2,"skill":"compare genres"},{"q":"What is the BIG surprise (twist) at the end of the play?","answer":"There is no school because it is Friday.","explanation":"The twist changes everything.","explanation_ar":"لا مدرسة لأن اليوم جمعة.","options":["Sami finds his shoe.","Mom is late.","There is no school because it is Friday.","The bus is broken."],"dok":2,"skill":"plot"},{"q":"What lesson does Sami learn?","answer":"Check things carefully before you rush.","explanation":"He will check the clock and calendar.","explanation_ar":"تحقق قبل أن تستعجل.","options":["Check things carefully before you rush.","Never wake up early.","Always wear one shoe.","Alarm clocks are bad."],"dok":3,"skill":"central message"}],"images":[{"id":"IMG-RW-L02-U6-LS2-V01","prompt":"Picture for the word 'alarm clock': a red alarm clock with two bells"},{"id":"IMG-RW-L02-U6-LS2-V02","prompt":"Picture for the word 'ring': an alarm clock shaking with sound lines"},{"id":"IMG-RW-L02-U6-LS2-V03","prompt":"Picture for the word 'miss': a bus driving away from a bus stop"},{"id":"IMG-RW-L02-U6-LS2-V04","prompt":"Picture for the word 'calendar': a wall calendar with Friday circled"},{"id":"IMG-RW-L02-U6-LS2-V05","prompt":"Picture for the word 'silly': a boy with a shirt on backward, laughing"},{"id":"IMG-RW-L02-U6-LS2-V06","prompt":"Picture for the word 'play': children acting on a small stage"},{"id":"IMG-RW-L02-U6-LS2-V07","prompt":"Picture for the word 'character': puppets of Sami, Mom and Lama"},{"id":"IMG-RW-L02-U6-LS2-01","prompt":"Sami rushes into the kitchen with one shoe while Lama laughs."},{"id":"IMG-RW-L02-U6-LS2-02","prompt":"Sami reads the calendar and sees it is Friday."},{"id":"IMG-RW-L02-U6-LS2-03","prompt":"A labelled play page showing characters, scene, lines and stage directions."}],"audio":[{"id":"AUD-RW-L02-U6-LS2-V01","script":"alarm clock. My alarm clock rings at six."},{"id":"AUD-RW-L02-U6-LS2-V02","script":"ring. The alarm clock did not ring."},{"id":"AUD-RW-L02-U6-LS2-V03","script":"miss. I missed the bus."},{"id":"AUD-RW-L02-U6-LS2-V04","script":"calendar. Look at the calendar."},{"id":"AUD-RW-L02-U6-LS2-V05","script":"silly. That was a silly mistake!"},{"id":"AUD-RW-L02-U6-LS2-V06","script":"play. We read a play in class."},{"id":"AUD-RW-L02-U6-LS2-V07","script":"character. Sami is a character in the play."},{"id":"AUD-RW-L02-U6-LS2-T1","script":"**Characters:** Sami, Mom, Lama (Sami's little sister) **Scene:** Sami's bedroom. It is eight o'clock in the morning. *(Sami is sleeping after the dawn prayer. His alarm clock is quiet.)* **MOM:** *(knocking on the door)* Sami! Wake up! It is eight o'clock! **SAMI:** *(jumping out of bed)* Oh no! My alarm clock did not ring! I am late for school! *(Sami puts on his shirt the wrong way and runs to the kitchen with one shoe.)* **LAMA:** *(laughing)* Sami, why are you running? **SAMI:** The school bus comes at seven o'clock! I missed it! **MOM:** *(smiling)* Sami, look at the calendar. What day is today? **SAMI:** *(reading slowly)* Friday… Oh! There is no school today! **LAMA:** Silly Sami! **SAMI:** *(laughing)* Tonight, I will check my alarm clock AND the calendar!"},{"id":"AUD-RW-L02-U6-LS2-VID","script":"Today we read a play! A play is a story that people act out. The Late Alarm Clock. Characters: Sami, Mom, Lama… Names in capitals tell who speaks. Words in brackets are stage directions – do them, don't say them! Stage directions show feelings: (laughing), (smiling), (reading slowly). Now you are the actors! Choose a part and read with feeling."}]},{"id":"RW-L02-U6-LS3","title":"Text features: headings, captions, bold words: \"A Day in the Life of a Baker\"","lesson_type":"strategy_paired_text","objectives":["find and use text features: title, headings, bold words and captions","explain what each text feature tells the reader","use headings to find information about a baker's day quickly"],"objectives_ar":["إيجاد خصائص النص واستخدامها: العنوان والعناوين الفرعية والكلمات الغامقة والتعليقات على الصور.","شرح ما تخبر به كل خاصية القارئ.","استخدام العناوين لإيجاد معلومات عن يوم الخباز بسرعة."],"success_criteria":["I can find a heading, a bold word and a caption.","I can say what each feature tells me.","I can use headings to find an answer fast."],"success_criteria_ar":["أستطيع إيجاد عنوان فرعي وكلمة غامقة وتعليق صورة.","أستطيع قول ما تخبرني به كل خاصية.","أستطيع استخدام العناوين لإيجاد الإجابة بسرعة."],"map_area":"Informational Text: Language, Craft, and Structure","vocabulary":[{"word":"baker","pos":"noun","ipa":"/ˈbeɪkər/","definition":"a person who makes and sells bread and cakes","arabic":"خبّاز","example":"The baker makes fresh bread.","image_id":"IMG-RW-L02-U6-LS3-V01","audio_id":"AUD-RW-L02-U6-LS3-V01","tier":"core"},{"word":"bakery","pos":"noun","ipa":"/ˈbeɪkəri/","definition":"a shop where bread is made and sold","arabic":"مخبز","example":"We buy bread at the bakery.","image_id":"IMG-RW-L02-U6-LS3-V02","audio_id":"AUD-RW-L02-U6-LS3-V02","tier":"core"},{"word":"dough","pos":"noun","ipa":"/doʊ/","definition":"flour and water mixed together to make bread","arabic":"عجين","example":"The baker mixes the dough.","image_id":"IMG-RW-L02-U6-LS3-V03","audio_id":"AUD-RW-L02-U6-LS3-V03","tier":"core"},{"word":"oven","pos":"noun","ipa":"/ˈʌvən/","definition":"a hot box for baking or cooking","arabic":"فرن","example":"The bread is in the oven.","image_id":"IMG-RW-L02-U6-LS3-V04","audio_id":"AUD-RW-L02-U6-LS3-V04","tier":"core"},{"word":"heading","pos":"noun","ipa":"/ˈhɛdɪŋ/","definition":"a short title for one part of a text","arabic":"عنوان فرعي","example":"The heading 'Morning' tells what the part is about.","image_id":"IMG-RW-L02-U6-LS3-V05","audio_id":"AUD-RW-L02-U6-LS3-V05","tier":"core"},{"word":"caption","pos":"noun","ipa":"/ˈkæpʃən/","definition":"words under a picture that tell about it","arabic":"تعليق الصورة","example":"Read the caption under the picture.","image_id":"IMG-RW-L02-U6-LS3-V06","audio_id":"AUD-RW-L02-U6-LS3-V06","tier":"core"},{"word":"bold","pos":"adjective","ipa":"/boʊld/","definition":"printed in thick, dark letters","arabic":"غامق / عريض","example":"Bold words are important words.","image_id":"IMG-RW-L02-U6-LS3-V07","audio_id":"AUD-RW-L02-U6-LS3-V07","tier":"core"}],"explanation":{"text":"Informational texts have **text features**: special parts that help readers **find** and **understand** information.\n\n**Title** – tells the topic of the whole text. **Headings** – short titles for each part; they help you find information **fast**.\n\n**Bold words** – important words in thick, dark letters; you can often find their meaning in a **glossary**. **Captions** – words under a picture that tell what the picture shows.","examples":["Title: **A Day in the Life of a Baker** → the whole text is about a baker's day.","Heading: **Early Morning** → this part tells what Mr. Yousef does very early.","Heading: **Evening** → this part tells when he goes to bed.","Bold word: **dough** → an important baking word (flour and water mixed).","Bold word: **oven** → an important word; check the glossary.","Caption: *Mr. Yousef takes hot bread out of the oven.* → tells what the picture shows.","Question: *When does Mr. Yousef clean the bakery?* → go to the heading **Afternoon**.","The play in Lesson 2 had **different** features: character names and stage directions.","Unit 4 link: *Clothes for Hot and Cold Places* also used headings (Hot places, Cold places…)."],"common_errors":["✗ I read every word to find one answer. → ✓ I look at the headings first to find the right part. (Use headings to find answers **fast**.)","✗ The caption is the title. → ✓ The caption is under the picture; the title is at the top. (Different places, different jobs.)","✗ Bold words are not important. → ✓ Bold words are important words. (Bold = important.)","✗ Mr. Yousef wake up at three. → ✓ Mr. Yousef wakes up at three o'clock. (One person → **wakes**.)","✗ He put the bread in a oven. → ✓ He puts the bread in an oven. (**an** before a vowel sound; **puts**.)","✗ The heading tell me about the evening. → ✓ The heading tells me about the evening. (One heading → **tells**.)"],"arabic":"النصوص المعلوماتية فيها خصائص نصية تساعد القارئ على إيجاد المعلومات وفهمها.\n\nالعنوان يخبر بموضوع النص كله، والعناوين الفرعية (headings) أسماء قصيرة لكل جزء تساعدك على إيجاد المعلومة بسرعة.\n\nالكلمات الغامقة (bold) كلمات مهمة تجد معناها غالبًا في المسرد، والتعليق (caption) كلمات تحت الصورة تخبر بما تُظهره.\n\nلإيجاد إجابة بسرعة: اقرأ السؤال، ثم ابحث عن العنوان الفرعي المناسب."},"video":{"script":[{"time":"00:00–00:20","narration":"Omar the Reporter visits a bakery at three o'clock in the morning! Yawn!","on_screen":"A Day in the Life of a Baker","visual":"Omar with a microphone outside a lit bakery under the stars."},{"time":"00:20–01:20","narration":"Mr. Yousef is a baker in Taif. His day starts very early!","on_screen":"(informational text)","visual":"Mr. Yousef mixes dough, bakes bread in the oven, sells fresh bread, cleans in the afternoon and goes to bed in the evening."},{"time":"01:20–01:55","narration":"Look at the text features! Title… headings… bold words… a caption!","on_screen":"title · heading · bold · caption","visual":"Each feature on the page glows and gets a label."},{"time":"01:55–02:30","narration":"Question: When does Mr. Yousef clean the bakery? Find the heading 'Afternoon' – there it is!","on_screen":"Use headings to find answers fast ⚡","visual":"A finger runs down the headings and stops at 'Afternoon'."},{"time":"02:30–02:50","narration":"Text features are like signs on a road. They help you find your way!","on_screen":"Features = signs 🪧","visual":"Road signs labelled with the feature names; Saqr flies along the road."}],"captions_ar":["عمر المراسل يزور مخبزًا في الثالثة فجرًا!","السيد يوسف خبّاز في الطائف، ويبدأ يومه مبكرًا جدًا!","انظر إلى خصائص النص: العنوان… العناوين الفرعية… الكلمات الغامقة… تعليق الصورة!","سؤال: متى ينظف السيد يوسف المخبز؟ ابحث عن عنوان Afternoon… ها هو!","خصائص النص مثل لافتات الطريق؛ تساعدك على إيجاد طريقك!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Mr. Yousef: friendly adult male baker. Omar (the Reporter) interviews him."},"texts":[{"type":"reading","title":"A Day in the Life of a Baker","body":"Mr. Yousef is a baker in Taif. His day starts very early!\n\n**Early Morning**\n\nMr. Yousef wakes up at three o'clock. He mixes flour and water to make **dough**.\n\n**Morning**\n\nAt six o'clock, he puts the bread in a hot **oven**. People come to buy fresh bread for breakfast.\n\n*Picture caption: Mr. Yousef takes hot bread out of the oven.*\n\n**Afternoon**\n\nHe cleans the bakery and orders more flour.\n\n**Evening**\n\nMr. Yousef goes to bed at eight o'clock because tomorrow is another busy day!","word_count":84,"audio_id":"AUD-RW-L02-U6-LS3-T1","id":"TXT-RW-L02-U6-LS3-1","genre":"informational","role":"paired","difficulty":"200L–350L","glossary":[{"word":"dough","definition":"flour and water mixed together to make bread","arabic":"عجين"},{"word":"oven","definition":"a hot box for cooking or baking","arabic":"فرن"},{"word":"bakery","definition":"a shop where people make and sell bread","arabic":"مخبز"}]}],"activities":[{"id":"RW-L02-U6-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *A Day in the Life of a Baker*. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Where does Mr. Yousef work?","answer":"at a bakery in Taif","explanation":"He is a baker in Taif.","explanation_ar":"في مخبز بالطائف.","options":["on a farm in Al-Ahsa","at a school","at a fire station","at a bakery in Taif"],"dok":1,"skill":"key details","text_id":"TXT-RW-L02-U6-LS3-1","stage":"controlled"},{"q":"What time does Mr. Yousef wake up?","answer":"at three o'clock","explanation":"Early Morning section.","explanation_ar":"الثالثة.","options":["at six o'clock","at three o'clock","at eight o'clock","at twelve o'clock"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"What does he mix to make dough?","answer":"flour and water","explanation":"Text: flour and water.","explanation_ar":"الدقيق والماء.","options":["milk and dates","flour and water","sugar and salt","rice and water"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When does he put the bread in the oven?","answer":"at six o'clock","explanation":"Morning section.","explanation_ar":"السادسة.","options":["at three o'clock","in the afternoon","at six o'clock","at eight o'clock"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does he do in the afternoon?","answer":"He cleans the bakery and orders more flour.","explanation":"Afternoon section.","explanation_ar":"ينظف ويطلب الدقيق.","options":["He cleans the bakery and orders more flour.","He sleeps.","He bakes cakes.","He goes to school."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why does he go to bed at eight o'clock?","answer":"Tomorrow is another busy day.","explanation":"Text: because tomorrow is another busy day.","explanation_ar":"لأن الغد يوم مزدحم.","options":["He is sick.","The bakery is closed forever.","He likes the dark.","Tomorrow is another busy day."],"dok":1,"skill":"reasons","stage":"controlled"}]},{"id":"RW-L02-U6-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Text features. Choose.","instructions_ar":"خصائص النص: اختر.","items":[{"q":"Which text feature is *Early Morning*?","answer":"a heading","explanation":"A short title for a part.","explanation_ar":"عنوان فرعي.","options":["a caption","a heading","a bold word in a sentence","a stage direction"],"dok":1,"skill":"text features","stage":"guided"},{"q":"Which word is printed in bold inside a sentence?","answer":"dough","explanation":"dough is bold.","explanation_ar":"dough.","options":["Mr. Yousef","breakfast","dough","flour"],"dok":1,"skill":"text features","stage":"guided"},{"q":"What does the caption tell you?","answer":"what the picture shows","explanation":"Captions describe pictures.","explanation_ar":"ما تُظهره الصورة.","options":["the title of the text","what the picture shows","the time he goes to bed","the meaning of every word"],"dok":1,"skill":"text features","stage":"guided"},{"q":"Which heading would you look under to find out what he does at six o'clock?","answer":"Morning","explanation":"Six o'clock is in the Morning part.","explanation_ar":"Morning.","options":["Morning","Evening","Afternoon","Early Morning"],"dok":2,"skill":"using headings","stage":"guided"},{"q":"Where can you find the meaning of *oven*?","answer":"in the glossary","explanation":"Bold words are in the glossary.","explanation_ar":"في المسرد.","options":["in the caption only","in the title","in the glossary","under the heading Evening"],"dok":2,"skill":"text features","stage":"guided"},{"q":"Why does the writer make *dough* and *oven* bold?","answer":"They are important words readers need to know.","explanation":"Bold = important.","explanation_ar":"كلمات مهمة.","options":["They are the names of people.","They are headings.","They are funny words.","They are important words readers need to know."],"dok":2,"skill":"author's purpose","stage":"guided"}]},{"id":"RW-L02-U6-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Text Feature Hunt.","instructions_ar":"أكمل جدول البحث عن خصائص النص.","items":[{"q":"Heading – where did you find *Afternoon*, and what does it tell you?","answer":"Before the third part; it tells what the baker does in the afternoon.","explanation":"Where + what.","explanation_ar":"أين + ماذا.","dok":1,"skill":"text features","stage":"freer"},{"q":"Bold word – write one bold word and what it means.","answer":"oven – a hot box for baking","explanation":"Word + meaning.","explanation_ar":"كلمة + معنى.","dok":1,"skill":"text features","stage":"freer"},{"q":"Caption – copy the caption and say why it helps.","answer":"Mr. Yousef takes hot bread out of the oven. It tells me what the picture shows.","explanation":"Caption + help.","explanation_ar":"التعليق + فائدته.","dok":2,"skill":"text features","stage":"freer"},{"q":"Title – what does the title tell you about the whole text?","answer":"It tells me the text is about one day of a baker's life.","explanation":"Topic of the text.","explanation_ar":"موضوع النص.","dok":2,"skill":"text features","stage":"freer"}]},{"id":"RW-L02-U6-LS3-A4","type":"open","stage":"production","instructions":"Writing: Use and make text features.","instructions_ar":"استخدم خصائص النص واصنعها.","items":[{"q":"Write a new heading and one sentence for Mr. Yousef's day.","answer":"Lunch Time – At twelve o'clock, Mr. Yousef eats lunch with his family.","explanation":"Heading + sentence.","explanation_ar":"عنوان + جملة.","dok":2,"skill":"writing features","stage":"production"},{"q":"Write a caption for a picture of people buying bread.","answer":"Families buy fresh bread for breakfast.","explanation":"Tell what the picture shows.","explanation_ar":"اشرح الصورة.","dok":2,"skill":"writing features","stage":"production"},{"q":"How is Mr. Yousef's day different from your day?","answer":"He wakes up at three o'clock, but I wake up at six o'clock.","explanation":"Compare with but.","explanation_ar":"قارن بـ but.","dok":3,"skill":"compare","stage":"production"},{"q":"Would you like to be a baker? Why or why not?","answer":"Yes, I would because I love fresh bread, but waking up at three is hard!","explanation":"Opinion + reason.","explanation_ar":"رأي + سبب.","dok":3,"skill":"opinion","stage":"production"}]},{"id":"RW-L02-U6-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"A Day in the Life of a Baker\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “A Day in the Life of a Baker”.","answer":"84 words","title":"A Day in the Life of a Baker","body":"Mr. Yousef is a baker in Taif. His day starts very early!\n\n**Early Morning**\n\nMr. Yousef wakes up at three o'clock. He mixes flour and water to make **dough**.\n\n**Morning**\n\nAt six o'clock, he puts the bread in a hot **oven**. People come to buy fresh bread for breakfast.\n\n*Picture caption: Mr. Yousef takes hot bread out of the oven.*\n\n**Afternoon**\n\nHe cleans the bakery and orders more flour.\n\n**Evening**\n\nMr. Yousef goes to bed at eight o'clock because tomorrow is another busy day!","words":84,"limit":106}],"time_limit_sec":106},{"id":"RW-L02-U6-LS3-ORG","type":"organizer","organizer":"Text Feature Hunt","instructions":"Organizer: For each feature, write the feature, where you found it and what it tells you (feature → where → what it tells me).","items":[{"q":"Title → where? → what it tells me","answer":"A Day in the Life of a Baker → at the top → the whole text is about a baker's day"},{"q":"Heading → where? → what it tells me","answer":"Early Morning → before the first part → what the baker does very early"},{"q":"Bold word → where? → what it tells me","answer":"dough → in the Early Morning part → an important word: flour and water mixed"},{"q":"Caption → where? → what it tells me","answer":"Mr. Yousef takes hot bread out of the oven. → under the picture → what the picture shows"}]}],"game":{"name":"Feature Detectives","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Feature finder: a page of a non-fiction text appears; the app calls a feature ('Tap a caption!'); the child taps it and chooses what it tells the reader. Fast correct taps fill a bakery oven with bread.","Each team gets a non-fiction book and a set of feature cards.","The teacher flips a feature card (e.g., 'caption').","Teams race to find that feature in their book.","The first team to show it AND say what it tells the reader wins a point.","Play until every feature has been found twice."],"data":[]},"exit_quiz":[{"q":"What do headings help readers do?","answer":"find information fast","explanation":"Headings are signs for each part.","explanation_ar":"إيجاد المعلومة بسرعة.","options":["act out a play","sing a song","draw a picture","find information fast"],"dok":1,"skill":"text features"},{"q":"Where is a caption?","answer":"under or next to a picture","explanation":"Captions go with pictures.","explanation_ar":"تحت الصورة.","options":["at the top of the text only","under or next to a picture","in the glossary","in brackets after a name"],"dok":1,"skill":"text features"},{"q":"A bakery is ___.","answer":"a shop where bread is made and sold","explanation":"Bakery = bread shop.","explanation_ar":"مخبز.","options":["a shop where bread is made and sold","a hot box for baking","flour and water","a kind of clock"],"dok":1,"skill":"vocabulary"},{"q":"*He puts the bread in a hot oven.* An *oven* is ___.","answer":"a hot box for baking","explanation":"Oven = hot box.","explanation_ar":"فرن.","options":["a kind of bread","a shop","a hot box for baking","a bed"],"dok":1,"skill":"vocabulary"},{"q":"Which is a heading in *A Day in the Life of a Baker*?","answer":"Afternoon","explanation":"Afternoon is a heading.","explanation_ar":"Afternoon.","options":["dough","Mr. Yousef takes hot bread out of the oven.","flour","Afternoon"],"dok":1,"skill":"text features"},{"q":"You want to know when the baker goes to bed. Which heading do you use?","answer":"Evening","explanation":"Bedtime is in the evening.","explanation_ar":"Evening.","options":["Morning","Evening","Early Morning","Afternoon"],"dok":2,"skill":"using headings"},{"q":"Which text feature tells you the topic of the WHOLE text?","answer":"the title","explanation":"Title = whole text.","explanation_ar":"العنوان.","options":["the title","a caption","one bold word","the glossary"],"dok":2,"skill":"text features"},{"q":"How is the baker text different from *The Late Alarm Clock*?","answer":"The baker text has headings and a caption; the play has character names and stage directions.","explanation":"Different genres, different features.","explanation_ar":"خصائص مختلفة.","options":["Both have stage directions.","The play has headings.","The baker text is a play.","The baker text has headings and a caption; the play has character names and stage directions."],"dok":3,"skill":"compare genres"},{"q":"Why does Mr. Yousef wake up so early?","answer":"to make fresh bread before people eat breakfast","explanation":"Bread must be ready for breakfast.","explanation_ar":"ليجهز الخبز قبل الفطور.","options":["because his alarm is broken","to go to school","to make fresh bread before people eat breakfast","because it is Friday"],"dok":3,"skill":"inference"},{"q":"Which new heading fits in the baker text?","answer":"Lunch Time","explanation":"It fits the time-of-day headings.","explanation_ar":"Lunch Time.","options":["Lunch Time","Silly Sami","Characters","Cold Places"],"dok":2,"skill":"text structure"}],"images":[{"id":"IMG-RW-L02-U6-LS3-V01","prompt":"Picture for the word 'baker': a baker in a white apron"},{"id":"IMG-RW-L02-U6-LS3-V02","prompt":"Picture for the word 'bakery': a small bakery shop front"},{"id":"IMG-RW-L02-U6-LS3-V03","prompt":"Picture for the word 'dough': hands kneading dough"},{"id":"IMG-RW-L02-U6-LS3-V04","prompt":"Picture for the word 'oven': a bakery oven with bread inside"},{"id":"IMG-RW-L02-U6-LS3-V05","prompt":"Picture for the word 'heading': a page with headings highlighted"},{"id":"IMG-RW-L02-U6-LS3-V06","prompt":"Picture for the word 'caption': a photo with a line of text under it"},{"id":"IMG-RW-L02-U6-LS3-V07","prompt":"Picture for the word 'bold': a sentence with one word in bold"},{"id":"IMG-RW-L02-U6-LS3-01","prompt":"Mr. Yousef takes hot bread out of a big oven."},{"id":"IMG-RW-L02-U6-LS3-02","prompt":"An organizer for hunting text features."},{"id":"IMG-RW-L02-U6-LS3-03","prompt":"Road signs showing text features."}],"audio":[{"id":"AUD-RW-L02-U6-LS3-V01","script":"baker. The baker makes fresh bread."},{"id":"AUD-RW-L02-U6-LS3-V02","script":"bakery. We buy bread at the bakery."},{"id":"AUD-RW-L02-U6-LS3-V03","script":"dough. The baker mixes the dough."},{"id":"AUD-RW-L02-U6-LS3-V04","script":"oven. The bread is in the oven."},{"id":"AUD-RW-L02-U6-LS3-V05","script":"heading. The heading 'Morning' tells what the part is about."},{"id":"AUD-RW-L02-U6-LS3-V06","script":"caption. Read the caption under the picture."},{"id":"AUD-RW-L02-U6-LS3-V07","script":"bold. Bold words are important words."},{"id":"AUD-RW-L02-U6-LS3-T1","script":"Mr. Yousef is a baker in Taif. His day starts very early! **Early Morning** Mr. Yousef wakes up at three o'clock. He mixes flour and water to make **dough**. **Morning** At six o'clock, he puts the bread in a hot **oven**. People come to buy fresh bread for breakfast. *Picture caption: Mr. Yousef takes hot bread out of the oven.* **Afternoon** He cleans the bakery and orders more flour. **Evening** Mr. Yousef goes to bed at eight o'clock because tomorrow is another busy day!"},{"id":"AUD-RW-L02-U6-LS3-VID","script":"Omar the Reporter visits a bakery at three o'clock in the morning! Yawn! Mr. Yousef is a baker in Taif. His day starts very early! Look at the text features! Title… headings… bold words… a caption! Question: When does Mr. Yousef clean the bakery? Find the heading 'Afternoon' – there it is! Text features are like signs on a road. They help you find your way!"}]},{"id":"RW-L02-U6-LS4","title":"Writing Skill: A first topic sentence","lesson_type":"writing_skill","objectives":["write a topic sentence that tells what a whole paragraph is about","choose details that match the topic sentence and find a detail that does not belong","indent the first line of a paragraph"],"objectives_ar":["كتابة جملة رئيسية تخبر بموضوع الفقرة كلها.","اختيار تفاصيل تناسب الجملة الرئيسية وإيجاد التفصيل الذي لا ينتمي.","ترك مسافة في بداية السطر الأول من الفقرة."],"success_criteria":["I can find the topic sentence in a paragraph.","I can write a topic sentence for a topic.","I can find a detail that does not belong."],"success_criteria_ar":["أستطيع إيجاد الجملة الرئيسية في الفقرة.","أستطيع كتابة جملة رئيسية لموضوع.","أستطيع إيجاد التفصيل الذي لا ينتمي."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"paragraph","pos":"noun","ipa":"/ˈpærəɡræf/","definition":"a group of sentences about one topic","arabic":"فقرة","example":"This paragraph is about Saturday.","image_id":"IMG-RW-L02-U6-LS4-V01","audio_id":"AUD-RW-L02-U6-LS4-V01","tier":"core"},{"word":"topic","pos":"noun","ipa":"/ˈtɑpɪk/","definition":"what something is about","arabic":"موضوع","example":"The topic is my favorite day.","image_id":"IMG-RW-L02-U6-LS4-V02","audio_id":"AUD-RW-L02-U6-LS4-V02","tier":"core"},{"word":"indent","pos":"verb","ipa":"/ɪnˈdɛnt/","definition":"to start the first line a little to the right","arabic":"يترك مسافة بادئة","example":"Indent the first line.","image_id":"IMG-RW-L02-U6-LS4-V03","audio_id":"AUD-RW-L02-U6-LS4-V03","tier":"core"},{"word":"belong","pos":"verb","ipa":"/bɪˈlɔŋ/","definition":"to be in the right group or place","arabic":"ينتمي","example":"This detail does not belong.","image_id":"IMG-RW-L02-U6-LS4-V04","audio_id":"AUD-RW-L02-U6-LS4-V04","tier":"core"},{"word":"library","pos":"noun","ipa":"/ˈlaɪbrɛri/","definition":"a place with many books you can read or borrow","arabic":"مكتبة","example":"Adam goes to the library on Saturday.","image_id":"IMG-RW-L02-U6-LS4-V05","audio_id":"AUD-RW-L02-U6-LS4-V05","tier":"core"},{"word":"borrow","pos":"verb","ipa":"/ˈbɑroʊ/","definition":"to take something and give it back later","arabic":"يستعير","example":"I borrow three books.","image_id":"IMG-RW-L02-U6-LS4-V06","audio_id":"AUD-RW-L02-U6-LS4-V06","tier":"core"},{"word":"main idea","pos":"noun","ipa":"/meɪn aɪˈdiə/","definition":"the most important idea","arabic":"الفكرة الرئيسية","example":"The topic sentence tells the main idea.","image_id":"IMG-RW-L02-U6-LS4-V07","audio_id":"AUD-RW-L02-U6-LS4-V07","tier":"core"}],"explanation":{"text":"A **paragraph** is a group of sentences about **one topic**. The first line is **indented** (it starts a little to the right).\n\nThe **topic sentence** is usually the **first** sentence. It tells the **main idea**: what the **whole paragraph** is about. It is like an **umbrella** over all the details.\n\nA good topic sentence is **not too big** (*I like many things.*) and **not too small** (*I borrow three books.* – that is a detail). Every detail must **belong** under the umbrella.","examples":["Topic sentence: **Saturday is my favorite day at the library.** (Adam)","Topic sentence: **My grandfather has a busy morning.**","Topic sentence: **Our school bus ride is always fun.**","Topic sentence: **Friday is a special day for my family.**","Topic sentence: **Mr. Yousef the baker starts his day very early.**","Too big: *I like many things.* → Better: **I like rainy days in Taif.**","Too small (a detail): *I eat an egg.* → Better: **My breakfast is quick and healthy.**","Does not belong: in Adam's paragraph, *My cousin has a new bike.* → **cross it out** – it is not about the library.","Opener ideas: *___ is my favorite… / My ___ is very busy. / Every ___, I ___.*"],"common_errors":["✗ I borrow three books. Saturday is my favorite day… → ✓ Saturday is my favorite day at the library. … I borrow three books. (Put the topic sentence **first**.)","✗ I like many things. → ✓ I like Saturdays at the library. (Make the topic sentence **specific**.)","✗ (no indent) → ✓     Saturday is my favorite day… (**Indent** the first line.)","✗ Adding 'My cousin has a new bike.' to a library paragraph → ✓ Leave it out – it does not belong. (Every detail must match the topic.)","✗ This paragraph is about… → ✓ Saturday is my favorite day at the library. (Don't announce – just tell the main idea.)","✗ My favorite day saturday. → ✓ Saturday is my favorite day. (Full sentence; capital for days.)"],"arabic":"الفقرة مجموعة من الجمل عن موضوع واحد، ونترك مسافة صغيرة في بداية سطرها الأول.\n\nالجملة الرئيسية (topic sentence) تأتي غالبًا أولًا، وتخبر بالفكرة الرئيسية للفقرة كلها، فهي مثل المظلة فوق كل التفاصيل.\n\nالجملة الرئيسية الجيدة ليست عامة جدًا (I like many things) ولا صغيرة جدًا كأنها تفصيل (I borrow three books).\n\nكل تفصيل يجب أن ينتمي إلى الموضوع؛ احذف أي جملة لا تتحدث عنه."},"video":{"script":[{"time":"00:00–00:15","narration":"Adam loves Saturdays! Let's read his paragraph.","on_screen":"Saturday at the Library","visual":"Adam (blue wheelchair) at the city library with his father and Ms. Huda."},{"time":"00:15–00:55","narration":"Saturday is my favorite day at the library. In the morning, I go to the city library…","on_screen":"(model text)","visual":"The first sentence glows coral; the indent arrow blinks."},{"time":"00:55–01:35","narration":"The topic sentence is like an umbrella. All the details stay under it!","on_screen":"Topic sentence = umbrella ☂️","visual":"An umbrella labelled with the topic sentence; detail drops sit under it."},{"time":"01:35–02:10","narration":"Oh no! 'My cousin has a new bike.' Does it belong? No! It is outside the umbrella.","on_screen":"Does it belong? ✘","visual":"One drop rolls out from under the umbrella and gets wet."},{"time":"02:10–02:45","narration":"Not too big, not too small – just right! Now write YOUR topic sentence.","on_screen":"Just right!","visual":"Three umbrellas: tiny, huge and just right; Saqr picks the right one."}],"captions_ar":["آدم يحب أيام السبت! لنقرأ فقرته.","السبت يومي المفضل في المكتبة. في الصباح أذهب إلى مكتبة المدينة…","الجملة الرئيسية مثل المظلة؛ كل التفاصيل تبقى تحتها!","«ابن عمي عنده دراجة جديدة» هل تنتمي؟ لا! إنها خارج المظلة.","ليست كبيرة جدًا ولا صغيرة جدًا، بل مناسبة! والآن اكتب جملتك الرئيسية."],"voice":"Narrator: American English, warm female teacher, speed 0.85. Adam reads his paragraph clearly and proudly."},"texts":[{"type":"model","title":"Saturday at the Library (by Adam)","body":"Saturday is my favorite day at the library. In the morning, I go to the city library with my father. Ms. Huda helps me find books about space. In the afternoon, I read in the quiet reading room, and my father reads the newspaper. Before we go home, I borrow three books. Saturday at the library makes me happy!","word_count":59,"audio_id":"AUD-RW-L02-U6-LS4-T1","id":"TXT-RW-L02-U6-LS4-1","genre":"model text","role":"model","difficulty":"200L–350L","glossary":[],"annotations":["**Saturday is my favorite day at the library.** – the **topic sentence**. It is the **first** sentence, and it tells the reader what the **whole paragraph** is about.","The paragraph starts with a small space: the first line is **indented**.","**In the morning… / In the afternoon… / Before we go home…** – every **detail** is about Adam's Saturday at the library. Time words keep the details in order.","No detail is about something else (like football or Eid). Every detail **matches** the topic sentence.","**Saturday at the library makes me happy!** – the **closing** says the topic again in a new way, with a feeling."]}],"activities":[{"id":"RW-L02-U6-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Where is the topic sentence in Adam's paragraph?","answer":"It is the first sentence.","explanation":"Saturday is my favorite day at the library.","explanation_ar":"الجملة الأولى.","options":["It is the last sentence.","It is in the middle.","It is the first sentence.","There is no topic sentence."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"What does a topic sentence tell the reader?","answer":"what the whole paragraph is about","explanation":"Topic sentence = main idea.","explanation_ar":"موضوع الفقرة كلها.","options":["what the whole paragraph is about","the last detail","the time","the writer's age"],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"A group of sentences about one topic is a ___.","answer":"paragraph","explanation":"Paragraph = sentences about one topic.","explanation_ar":"فقرة.","options":["caption","heading","glossary","paragraph"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Adam takes books home and gives them back later. He ___ them.","answer":"borrows","explanation":"Borrow = take and give back.","explanation_ar":"يستعيرها.","options":["bakes","borrows","rings","misses"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"When you *indent*, you ___.","answer":"start the first line a little to the right","explanation":"Indent = small space at the start.","explanation_ar":"تترك مسافة بادئة.","options":["write in bold","start the first line a little to the right","skip the topic sentence","draw a picture"],"dok":1,"skill":"paragraph form","stage":"controlled"},{"q":"Which detail does NOT belong in Adam's library paragraph?","answer":"My cousin has a new bike.","explanation":"A bike is not about the library.","explanation_ar":"الدراجة لا تنتمي.","options":["Ms. Huda helps me find books.","I read in the quiet reading room.","My cousin has a new bike.","I borrow three books."],"dok":2,"skill":"relevant details","stage":"controlled"}]},{"id":"RW-L02-U6-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Choose the best topic sentence.","instructions_ar":"اختر أفضل جملة رئيسية.","items":[{"q":"Details: *I wake up at six. I wash my face. I eat breakfast. I catch the bus.* Best topic sentence?","answer":"My school mornings are very busy.","explanation":"It covers all the details.","explanation_ar":"تغطي كل التفاصيل.","options":["My school mornings are very busy.","I like football.","I eat breakfast.","The bus is yellow."],"dok":2,"skill":"topic sentence","stage":"guided"},{"q":"Details: *We visit Grandpa. We eat lunch together. We go to the mosque. We play in the garden.* Best topic sentence?","answer":"Friday is a special day for my family.","explanation":"Friday activities with family.","explanation_ar":"يوم الجمعة يوم مميز لعائلتي.","options":["Friday is a special day for my family.","Grandpa has a palm tree.","I like many things.","We go to the mosque."],"dok":2,"skill":"topic sentence","stage":"guided"},{"q":"Which topic sentence is TOO BIG?","answer":"I like many things.","explanation":"Too general to write about.","explanation_ar":"عامة جدًا.","options":["I love rainy days in Taif.","My bedroom is small and cozy.","Our school garden is beautiful.","I like many things."],"dok":2,"skill":"topic sentence quality","stage":"guided"},{"q":"Which sentence about breakfast is a DETAIL, not a topic sentence?","answer":"I eat one boiled egg.","explanation":"It is too small to cover a paragraph.","explanation_ar":"تفصيل صغير.","options":["My breakfast is quick and healthy.","Mornings at my house are noisy.","Weekends are my favorite days.","I eat one boiled egg."],"dok":2,"skill":"topic vs. detail","stage":"guided"},{"q":"Topic sentence: *Mr. Yousef the baker starts his day very early.* Which detail belongs?","answer":"He wakes up at three o'clock.","explanation":"It is about the baker's early start.","explanation_ar":"يستيقظ في الثالثة.","options":["Faris has a toy car.","He wakes up at three o'clock.","Taif roses smell sweet.","Sami's alarm clock is red."],"dok":1,"skill":"relevant details","stage":"guided"},{"q":"Topic sentence: *Our school bus ride is always fun.* Which detail does NOT belong?","answer":"My mother makes date cookies.","explanation":"Cookies at home are not about the bus ride.","explanation_ar":"الكعك لا ينتمي.","options":["We sing songs on the bus.","Omar tells funny jokes.","My mother makes date cookies.","We look at the camels on the road."],"dok":2,"skill":"relevant details","stage":"guided"}]},{"id":"RW-L02-U6-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"This ________ has five sentences about my school.","answer":"paragraph","explanation":"Group of sentences about one topic.","explanation_ar":"فقرة.","stage":"freer"},{"q":"The ________ of Adam's paragraph is his Saturday at the library.","answer":"topic","explanation":"What it is about.","explanation_ar":"الموضوع.","stage":"freer"},{"q":"Remember to ________ the first line of your paragraph.","answer":"indent","explanation":"Start a little to the right.","explanation_ar":"اترك مسافة.","stage":"freer"},{"q":"A sentence about bikes does not ________ in a library paragraph.","answer":"belong","explanation":"Be in the right group.","explanation_ar":"ينتمي.","stage":"freer"},{"q":"The topic sentence tells the ________ of the paragraph.","answer":"main idea","explanation":"Most important idea.","explanation_ar":"الفكرة الرئيسية.","stage":"freer"},{"q":"Ms. Huda works in the school ________.","answer":"library","explanation":"Place with many books.","explanation_ar":"مكتبة.","stage":"freer"}]},{"id":"RW-L02-U6-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write topic sentences.","instructions_ar":"اكتب جملًا رئيسية.","items":[{"q":"Write a topic sentence about your bedroom.","answer":"My bedroom is small, but it is very cozy.","explanation":"Main idea about your bedroom.","explanation_ar":"فكرة رئيسية عن غرفتك.","dok":2,"skill":"topic sentence","stage":"production"},{"q":"Write a topic sentence about your favorite day of the week.","answer":"Thursday is my favorite school day.","explanation":"Day + why it is special.","explanation_ar":"اليوم + لماذا هو مميز.","dok":2,"skill":"topic sentence","stage":"production"},{"q":"Fix this topic sentence. It is too small: *I drink milk.*","answer":"My breakfast is quick and healthy.","explanation":"Make it cover a whole paragraph.","explanation_ar":"اجعلها تغطي الفقرة.","dok":3,"skill":"revising","stage":"production"},{"q":"Write a topic sentence and two details that belong.","answer":"My grandfather has a busy morning. He wakes up for the Fajr prayer. Then, he waters his palm trees.","explanation":"Topic sentence + 2 details.","explanation_ar":"جملة رئيسية + تفصيلان.","dok":3,"skill":"paragraph","stage":"production"}]}],"game":{"name":"Umbrella Catch","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Umbrella catcher: a topic sentence sits on an umbrella; detail raindrops fall; the child moves the umbrella to catch drops that belong and lets the others fall. Catching a wrong drop makes the umbrella shake.","The teacher holds up an umbrella with a topic sentence.","Teams take turns drawing a detail card and reading it aloud.","The team decides: 'Under the umbrella!' (belongs) or 'Let it fall!' (does not belong).","Correct decision = 1 point; a reason that explains it = 1 bonus point.","Change the topic sentence after six cards."],"data":[]},"exit_quiz":[{"q":"Where is the topic sentence usually found in a paragraph?","answer":"first","explanation":"Usually first.","explanation_ar":"أولًا.","options":["last","in the middle","first","in the title"],"dok":1,"skill":"topic sentence"},{"q":"A topic sentence is like an umbrella because ___.","answer":"it covers all the details","explanation":"It covers the whole paragraph.","explanation_ar":"يغطي كل التفاصيل.","options":["it keeps you dry","it is always short","it covers all the details","it comes at the end"],"dok":1,"skill":"concept"},{"q":"*Indent the first line.* What should the first line look like?","answer":"It starts a little to the right.","explanation":"Indent = small space.","explanation_ar":"تبدأ بمسافة.","options":["It is in bold.","It starts a little to the right.","It is under a picture.","It is in brackets."],"dok":1,"skill":"paragraph form"},{"q":"*The main idea* is ___.","answer":"the most important idea","explanation":"Main idea = most important idea.","explanation_ar":"الفكرة الأهم.","options":["the most important idea","the last word","a small detail","the title of a book"],"dok":1,"skill":"vocabulary"},{"q":"Which topic sentence about rainy days is just right?","answer":"I love rainy days in Taif.","explanation":"Clear and specific.","explanation_ar":"مناسبة.","options":["I like many things.","Rain.","I see one raindrop.","I love rainy days in Taif."],"dok":2,"skill":"topic sentence quality"},{"q":"Topic sentence: *My little sister Lama is very funny.* Which detail belongs?","answer":"She makes funny faces at dinner.","explanation":"It is about Lama being funny.","explanation_ar":"تنتمي.","options":["The baker wakes up at three.","Palm trees need water.","The bus comes at seven.","She makes funny faces at dinner."],"dok":2,"skill":"relevant details"},{"q":"Details: *We plant mint. We water the roses. We pick tomatoes.* Which topic sentence fits?","answer":"We work hard in our school garden.","explanation":"It covers all the garden details.","explanation_ar":"تناسب التفاصيل.","options":["We work hard in our school garden.","I have a new bike.","Tomatoes are red.","My alarm clock is late."],"dok":2,"skill":"topic sentence"},{"q":"Fix it: *my favorite day saturday.*","answer":"Saturday is my favorite day.","explanation":"Full sentence with capitals.","explanation_ar":"جملة كاملة.","options":["my Favorite day Saturday.","Saturday is my favorite day.","Saturday my favorite day.","My favorite day saturday is."],"dok":2,"skill":"editing"},{"q":"Why does a paragraph need a topic sentence?","answer":"It tells the reader what the paragraph is about before the details.","explanation":"It guides the reader.","explanation_ar":"يخبر القارئ بالموضوع.","options":["It makes the paragraph longer.","It tells the reader what the paragraph is about before the details.","It replaces the details.","It is only for poems."],"dok":3,"skill":"purpose"},{"q":"A friend's paragraph about Eid has the sentence *My bike is red.* What should the friend do?","answer":"Take it out because it does not belong.","explanation":"Remove details that do not belong.","explanation_ar":"يحذفها.","options":["Take it out because it does not belong.","Make it the topic sentence.","Write it two times.","Put it in bold."],"dok":3,"skill":"revising"}],"images":[{"id":"IMG-RW-L02-U6-LS4-V01","prompt":"Picture for the word 'paragraph': a page with one paragraph boxed"},{"id":"IMG-RW-L02-U6-LS4-V02","prompt":"Picture for the word 'topic': a big label 'TOPIC' over a paragraph"},{"id":"IMG-RW-L02-U6-LS4-V03","prompt":"Picture for the word 'indent': a paragraph with an arrow at the indent"},{"id":"IMG-RW-L02-U6-LS4-V04","prompt":"Picture for the word 'belong': a banana in a row of apples"},{"id":"IMG-RW-L02-U6-LS4-V05","prompt":"Picture for the word 'library': shelves of books in a library"},{"id":"IMG-RW-L02-U6-LS4-V06","prompt":"Picture for the word 'borrow': a child taking books at the library desk"},{"id":"IMG-RW-L02-U6-LS4-V07","prompt":"Picture for the word 'main idea': an umbrella over smaller ideas"},{"id":"IMG-RW-L02-U6-LS4-01","prompt":"Adam borrows space books from Ms. Huda at the library."},{"id":"IMG-RW-L02-U6-LS4-02","prompt":"An umbrella showing a topic sentence covering its details."},{"id":"IMG-RW-L02-U6-LS4-03","prompt":"A paragraph showing the indent, topic sentence and closing."}],"audio":[{"id":"AUD-RW-L02-U6-LS4-V01","script":"paragraph. This paragraph is about Saturday."},{"id":"AUD-RW-L02-U6-LS4-V02","script":"topic. The topic is my favorite day."},{"id":"AUD-RW-L02-U6-LS4-V03","script":"indent. Indent the first line."},{"id":"AUD-RW-L02-U6-LS4-V04","script":"belong. This detail does not belong."},{"id":"AUD-RW-L02-U6-LS4-V05","script":"library. Adam goes to the library on Saturday."},{"id":"AUD-RW-L02-U6-LS4-V06","script":"borrow. I borrow three books."},{"id":"AUD-RW-L02-U6-LS4-V07","script":"main idea. The topic sentence tells the main idea."},{"id":"AUD-RW-L02-U6-LS4-T1","script":"Saturday is my favorite day at the library. In the morning, I go to the city library with my father. Ms. Huda helps me find books about space. In the afternoon, I read in the quiet reading room, and my father reads the newspaper. Before we go home, I borrow three books. Saturday at the library makes me happy!"},{"id":"AUD-RW-L02-U6-LS4-VID","script":"Adam loves Saturdays! Let's read his paragraph. Saturday is my favorite day at the library. In the morning, I go to the city library… The topic sentence is like an umbrella. All the details stay under it! Oh no! 'My cousin has a new bike.' Does it belong? No! It is outside the umbrella. Not too big, not too small – just right! Now write YOUR topic sentence."}]},{"id":"RW-L02-U6-LS5","title":"Writing Workshop: My Busy Day","lesson_type":"writing_workshop","objectives":["plan a paragraph about a busy day with a topic sentence, time-ordered details and a closing","write a 6–7-sentence paragraph with an indent, time words and and/but","revise for details that belong, edit and publish the paragraph on a clock-shaped page"],"objectives_ar":["التخطيط لفقرة عن يوم مزدحم بجملة رئيسية وتفاصيل مرتبة زمنيًا وخاتمة.","كتابة فقرة من 6–7 جمل مع مسافة بادئة وكلمات الوقت وand/but.","التحسين بحذف التفاصيل غير المنتمية، ثم التدقيق والنشر على صفحة على شكل ساعة."],"success_criteria":["I can write a topic sentence for my paragraph.","I can put my details in time order with time words.","I can check that every detail belongs."],"success_criteria_ar":["أستطيع كتابة جملة رئيسية لفقرتي.","أستطيع ترتيب تفاصيلي زمنيًا بكلمات الوقت.","أستطيع التحقق من أن كل تفصيل ينتمي إلى الموضوع."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"busy","pos":"adjective","ipa":"/ˈbɪzi/","definition":"with a lot to do","arabic":"مشغول / مزدحم","example":"Tuesday is a busy day.","image_id":"IMG-RW-L02-U6-LS5-V01","audio_id":"AUD-RW-L02-U6-LS5-V01","tier":"core"},{"word":"practice","pos":"noun","ipa":"/ˈpræktɪs/","definition":"a time when you do something again and again to get better","arabic":"تمرين / تدريب","example":"I have football practice at four o'clock.","image_id":"IMG-RW-L02-U6-LS5-V02","audio_id":"AUD-RW-L02-U6-LS5-V02","tier":"core"},{"word":"homework","pos":"noun","ipa":"/ˈhoʊmwɝk/","definition":"school work you do at home","arabic":"واجب منزلي","example":"I do my homework after lunch.","image_id":"IMG-RW-L02-U6-LS5-V03","audio_id":"AUD-RW-L02-U6-LS5-V03","tier":"core"},{"word":"dinner","pos":"noun","ipa":"/ˈdɪnər/","definition":"the meal we eat in the evening","arabic":"العشاء","example":"We eat dinner at seven o'clock.","image_id":"IMG-RW-L02-U6-LS5-V04","audio_id":"AUD-RW-L02-U6-LS5-V04","tier":"core"},{"word":"bedtime","pos":"noun","ipa":"/ˈbɛdtaɪm/","definition":"the time when you go to bed","arabic":"وقت النوم","example":"My bedtime is nine o'clock.","image_id":"IMG-RW-L02-U6-LS5-V05","audio_id":"AUD-RW-L02-U6-LS5-V05","tier":"core"},{"word":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","definition":"needing rest or sleep","arabic":"متعب","example":"I am tired after a busy day.","image_id":"IMG-RW-L02-U6-LS5-V06","audio_id":"AUD-RW-L02-U6-LS5-V06","tier":"core"},{"word":"schedule","pos":"noun","ipa":"/ˈskɛdʒul/","definition":"a plan that shows what you do and when","arabic":"جدول","example":"My schedule is on the fridge.","image_id":"IMG-RW-L02-U6-LS5-V07","audio_id":"AUD-RW-L02-U6-LS5-V07","tier":"core"}],"explanation":{"text":"Write **one paragraph** about a busy day: **indent** the first line and start with a **topic sentence**.\n\nUse the **Hamburger Plan**: **topic sentence** → **details in time order** (morning → afternoon → evening → night) → **closing** (a feeling).\n\nUse **time words** (*in the morning, at four o'clock, after that, at night*) and join some ideas with **, and** / **, but**. Check that **every detail belongs**.","examples":["Topic sentence: **Tuesday is my busiest day of the week.**","Detail (morning): **I wake up at five o'clock for the Fajr prayer.**","Detail (morning): **At seven o'clock, I take the bus to school.**","Detail (afternoon): **After lunch, I do my homework, and my mother checks it.**","Detail (afternoon): **At four o'clock, I have football practice with my team.**","Detail (evening): **We eat dinner together at seven o'clock, but my father comes home late.**","Closing: **At bedtime, I am tired, but I am happy!**","Another topic sentence: **My Thursday is full of fun.**","Does not belong: *My uncle's car is white.* → not about my busy day."],"common_errors":["✗ (no topic sentence – starts with 'I wake up at five.') → ✓ Tuesday is my busiest day of the week. I wake up at five… (Start with a topic sentence.)","✗ At night I eat breakfast. → ✓ In the morning, I eat breakfast. (Keep details in **time order**.)","✗ I go to school at 7 clock. → ✓ I go to school at seven o'clock. (Say **at … o'clock**.)","✗ I have practice in four o'clock. → ✓ I have practice at four o'clock. (**at** + time.)","✗ My uncle's car is white. → ✓ (cross it out) (Remove details that do not belong.)","✗ I am tired but I am happy. → ✓ I am tired, but I am happy. (Comma before **but**.)"],"arabic":"اكتب فقرة واحدة عن يوم مزدحم: اترك مسافة بادئة وابدأ بجملة رئيسية.\n\nاستخدم خطة الهامبرغر: الجملة الرئيسية ← تفاصيل مرتبة زمنيًا (صباح ← بعد الظهر ← مساء ← ليل) ← خاتمة بشعور.\n\nاستخدم كلمات الوقت (in the morning, at four o'clock, after that, at night)، واربط بعض الأفكار بـ , and و, but.\n\nتحقق من أن كل تفصيل ينتمي إلى موضوع يومك، واحذف ما لا ينتمي."},"video":{"script":[{"time":"00:00–00:15","narration":"Omar has a VERY busy Tuesday! Let's help him write about it.","on_screen":"My Busy Day","visual":"Omar runs past a clock with a ball, a book and a lunchbox."},{"time":"00:15–00:50","narration":"Plan: topic sentence on top; details in time order; closing at the bottom.","on_screen":"1 Plan – Hamburger + day line","visual":"A hamburger next to a day line from sunrise to moon."},{"time":"00:50–01:40","narration":"Draft: Tuesday is my busiest day of the week. I wake up at five o'clock for the Fajr prayer…","on_screen":"2 Draft – topic sentence + time order","visual":"Each sentence pins to the day line at the right time."},{"time":"01:40–02:05","narration":"Revise: 'My uncle's car is white.' Does it belong? No! Cross it out.","on_screen":"3 Revise – does it belong?","visual":"A sentence floats off the day line and pops."},{"time":"02:05–02:30","narration":"Edit: indent, capitals, at + o'clock, commas before and/but – check!","on_screen":"4 Edit ⇥ A , at","visual":"An indent arrow blinks; commas hop into place."},{"time":"02:30–02:55","narration":"Publish: Omar copies his paragraph inside a big clock and reads it to the class!","on_screen":"5 Publish ⏰","visual":"A class wall of clock-shaped pages titled 'Our Busy Days'."}],"captions_ar":["عند عمر يوم ثلاثاء مزدحم جدًا! لنساعده على الكتابة عنه.","التخطيط: الجملة الرئيسية في الأعلى، والتفاصيل مرتبة زمنيًا، والخاتمة في الأسفل.","المسودة: الثلاثاء أكثر أيام أسبوعي ازدحامًا. أستيقظ في الخامسة لصلاة الفجر…","التحسين: «سيارة عمي بيضاء» هل تنتمي؟ لا! احذفها.","التدقيق: المسافة البادئة، والحروف الكبيرة، وat مع o'clock، والفواصل قبل and/but.","النشر: ينسخ عمر فقرته داخل ساعة كبيرة ويقرؤها للفصل!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Omar reads his paragraph energetically."},"texts":[],"activities":[{"id":"RW-L02-U6-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is the best topic sentence for *My Busy Day*?","answer":"Tuesday is my busiest day of the week.","explanation":"It tells the main idea.","explanation_ar":"تخبر بالفكرة الرئيسية.","options":["Tuesday is my busiest day of the week.","I have a pencil.","Dinner.","My uncle's car is white."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"Omar goes to the field at four o'clock to get better at football. He has ___.","answer":"practice","explanation":"Practice = training.","explanation_ar":"تمرين.","options":["practice","bedtime","dinner","a schedule"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A plan that shows what you do and when is a ___.","answer":"schedule","explanation":"Schedule = time plan.","explanation_ar":"جدول.","options":["caption","schedule","heading","pot"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"After a long day, Omar needs rest. He is ___.","answer":"tired","explanation":"Needs rest = tired.","explanation_ar":"متعب.","options":["early","busy","tired","silly"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which detail about football practice uses the time correctly?","answer":"At four o'clock, I have football practice.","explanation":"at + o'clock.","explanation_ar":"صحيحة.","options":["In four o'clock, I have football practice.","On four o'clock, I have practice.","At four o'clock, I have football practice.","At four clock, I have practice."],"dok":1,"skill":"prepositions of time","stage":"controlled"},{"q":"Which closing sentence ends a busy-day paragraph well?","answer":"At bedtime, I am tired, but I am happy!","explanation":"A feeling to finish.","explanation_ar":"خاتمة بشعور.","options":["I wake up at five.","Tuesday is busy.","Where is my bag?","At bedtime, I am tired, but I am happy!"],"dok":2,"skill":"closing","stage":"controlled"}]},{"id":"RW-L02-U6-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the sentences or words in order.","instructions_ar":"رتّب الجمل أو الكلمات.","items":[{"q":"Order Omar's paragraph.","answer":"Tuesday is my busiest day. → I wake up at five o'clock. → After lunch, I do my homework. → At bedtime, I am tired but happy.","explanation":"Topic sentence → time-order details → closing.","explanation_ar":"رئيسية ← تفاصيل مرتبة ← خاتمة.","stage":"guided","parts":["At bedtime, I am tired but happy.","Tuesday is my busiest day.","I wake up at five o'clock.","After lunch, I do my homework."],"target":["Tuesday is my busiest day.","I wake up at five o'clock.","After lunch, I do my homework.","At bedtime, I am tired but happy."]},{"q":"Build a morning detail.","answer":"In the morning, → I take → the bus → to school.","explanation":"Time phrase + comma + sentence.","explanation_ar":"عبارة وقت + فاصلة + جملة.","stage":"guided","parts":["In the morning,","the bus","to school.","I take"],"target":["In the morning,","I take","the bus","to school."]},{"q":"Build an afternoon detail.","answer":"At four o'clock, → I have → football practice.","explanation":"at + time + comma.","explanation_ar":"at + وقت + فاصلة.","stage":"guided","parts":["I have","At four o'clock,","football practice."],"target":["At four o'clock,","I have","football practice."]},{"q":"Build an evening but sentence.","answer":"We eat dinner at seven, → but → my father comes home late.","explanation":"Detail + , but + different idea.","explanation_ar":"تفصيل + , but + فكرة مختلفة.","stage":"guided","parts":["We eat dinner at seven,","my father comes home late.","but"],"target":["We eat dinner at seven,","but","my father comes home late."]},{"q":"Build a night detail.","answer":"My bedtime is nine o'clock.","explanation":"Subject + is + time.","explanation_ar":"فاعل + is + وقت.","stage":"guided","parts":["nine","My","o'clock.","is","bedtime"],"target":["My","bedtime","is","nine","o'clock."]},{"q":"Build a topic sentence about Thursday.","answer":"Thursday is full of fun.","explanation":"A short topic sentence.","explanation_ar":"جملة رئيسية قصيرة.","stage":"guided","parts":["fun.","Thursday","is","of","full"],"target":["Thursday","is","full","of","fun."]}]},{"id":"RW-L02-U6-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your paragraph.","instructions_ar":"خطط لفقرتك.","items":[{"q":"Which day will you write about? Write your topic sentence.","answer":"Thursday is my busiest school day.","explanation":"Day + main idea.","explanation_ar":"اليوم + الفكرة الرئيسية.","dok":1,"skill":"planning","stage":"freer"},{"q":"Write notes for your morning and afternoon.","answer":"Morning: wake up at six, school bus. Afternoon: homework, swimming at four.","explanation":"Notes in time order.","explanation_ar":"ملاحظات مرتبة زمنيًا.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write notes for your evening and night.","answer":"Evening: Maghrib prayer, dinner with Grandpa. Night: read a story, bedtime at nine.","explanation":"Notes in time order.","explanation_ar":"ملاحظات مرتبة زمنيًا.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write your closing feeling.","answer":"I am tired, but I love my busy Thursday!","explanation":"A feeling.","explanation_ar":"شعور.","dok":1,"skill":"planning","stage":"freer"}]},{"id":"RW-L02-U6-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your paragraph. Then revise, edit and publish it.","instructions_ar":"اكتب فقرتك ثم حسّنها ودققها وانشرها.","items":[{"q":"Write your topic sentence and your morning details. Remember to indent.","answer":"Tuesday is my busiest day of the week. I wake up at five o'clock for the Fajr prayer. At seven o'clock, I take the bus to school.","explanation":"Indent + topic sentence + morning.","explanation_ar":"مسافة + رئيسية + الصباح.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your afternoon and evening details. Use , and or , but.","answer":"After lunch, I do my homework, and my mother checks it. At four o'clock, I have football practice. We eat dinner at seven, but my father comes home late.","explanation":"Time order + and/but.","explanation_ar":"ترتيب زمني + and/but.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing.","answer":"At bedtime, I am tired, but I am happy!","explanation":"Feeling sentence.","explanation_ar":"جملة شعور.","dok":1,"skill":"writing","stage":"production"},{"q":"Did you cross out a detail that does not belong? Write it and say why.","answer":"I crossed out 'My uncle's car is white' because it is not about my busy day.","explanation":"Revision + because.","explanation_ar":"تحسين + because.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L02-U6-LS5-ORG","type":"organizer","organizer":"Hamburger Plan + Day Line","instructions":"Organizer: Write your topic sentence on the top bun, one detail for each time of day on the layers and your closing on the bottom bun.","items":[{"q":"Top bun – topic sentence","answer":"Tuesday is my busiest day of the week."},{"q":"Morning detail","answer":"wake up at five for Fajr; bus at seven"},{"q":"Afternoon detail (and/but)","answer":"homework after lunch, and my mother checks it; practice at four"},{"q":"Evening detail","answer":"dinner at seven, but my father comes home late"},{"q":"Night detail","answer":"bedtime at nine"},{"q":"Bottom bun – closing (feeling)","answer":"At bedtime, I am tired, but I am happy!"}]},{"id":"RW-L02-U6-LS5-WR","type":"writing","instructions":"Writing: Write \"My Busy Day\": a 6–7-sentence paragraph with a topic sentence, details in time order and a closing. Write \"My Busy Day\": a 6–7-sentence paragraph with a topic sentence, details in time order and a closing.","instructions_ar":"اكتب «يومي المزدحم»: فقرة من 6–7 جمل فيها جملة رئيسية وتفاصيل مرتبة زمنيًا وخاتمة.","prompt":"Write \"My Busy Day\": a 6–7-sentence paragraph with a topic sentence, details in time order and a closing.","checklist":["I indented the first line.","My first sentence is a topic sentence.","My details are in time order.","I used at least three time words (in the morning, at … o'clock, after that…).","Every detail belongs to my topic.","I used , and or , but one time.","I wrote a closing sentence; capitals and periods are correct."],"rubric_id":"RW-RUBRIC-5T","min_words":55,"max_words":120,"organizer":"Hamburger Plan + Day Line (topic sentence – time-ordered details – closing)","items":[{"q":"Write \"My Busy Day\": a 6–7-sentence paragraph with a topic sentence, details in time order and a closing.","answer":"Tuesday is my busiest day of the week. I wake up at five o'clock for the Fajr prayer. At seven o'clock, I take the bus to school. After lunch, I do my homework, and my mother checks it. At four o'clock, I have football practice with my team. We eat dinner together at seven o'clock, but my father comes home late. At bedtime, I am tired, but I am happy!","_w":{"checklist":["I indented the first line.","My first sentence is a topic sentence.","My details are in time order.","I used at least three time words (in the morning, at … o'clock, after that…).","Every detail belongs to my topic.","I used , and or , but one time.","I wrote a closing sentence; capitals and periods are correct."],"min":55,"max":120}}]}],"game":{"name":"Beat the Clock","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Clock builder: sentence strips appear around a clock face; the child drags them into time order inside the clock and drops off-topic strips in the bin. Beat the timer to earn a golden alarm clock.","Teams get an envelope of strips.","Start the timer (3 minutes).","Teams put the topic sentence first, details in time order and the closing last.","Teams remove the two strips that do not belong.","A correct paragraph read aloud before time runs out = 3 points."],"data":[]},"exit_quiz":[{"q":"What should the first line of a paragraph have?","answer":"an indent","explanation":"Indent the first line.","explanation_ar":"مسافة بادئة.","options":["a caption","a heading","a stage direction","an indent"],"dok":1,"skill":"paragraph form"},{"q":"Where does the topic sentence go in *My Busy Day*?","answer":"first","explanation":"Topic sentence first.","explanation_ar":"أولًا.","options":["last","after the closing","first","in the title only"],"dok":1,"skill":"topic sentence"},{"q":"Which order is best for busy-day details?","answer":"morning → afternoon → evening → night","explanation":"Time order.","explanation_ar":"الترتيب الزمني.","options":["morning → afternoon → evening → night","night → morning → evening → afternoon","evening → morning → night → afternoon","any order"],"dok":1,"skill":"time order"},{"q":"*My bedtime is nine o'clock.* *Bedtime* is ___.","answer":"the time when you go to bed","explanation":"Bedtime = time for bed.","explanation_ar":"وقت النوم.","options":["the time when you go to bed","the time you wake up","a kind of bed","breakfast time"],"dok":1,"skill":"vocabulary"},{"q":"Which detail does NOT belong in a paragraph about a busy school day?","answer":"Camels can drink a lot of water.","explanation":"Camels are not about my day.","explanation_ar":"الجمال لا تنتمي.","options":["I take the bus at seven o'clock.","I do my homework after lunch.","I have practice at four o'clock.","Camels can drink a lot of water."],"dok":2,"skill":"relevant details"},{"q":"Which detail about homework is correct?","answer":"After lunch, I do my homework.","explanation":"Comma + correct verb.","explanation_ar":"صحيحة.","options":["After lunch I does my homework.","After lunch, I do my homework.","After lunch, I do homeworks.","After lunch, my homework I do."],"dok":2,"skill":"editing"},{"q":"Fix it: *We eat dinner at seven but my father comes home late.*","answer":"We eat dinner at seven, but my father comes home late.","explanation":"Comma before but.","explanation_ar":"فاصلة قبل but.","options":["We eat dinner at seven but, my father comes home late.","We eat dinner, at seven but my father comes home late.","We eat dinner at seven, but my father comes home late.","We eat dinner at seven but my father, comes home late."],"dok":2,"skill":"commas"},{"q":"Why do writers use time words in a busy-day paragraph?","answer":"to show when things happen and keep them in order","explanation":"Time words organize details.","explanation_ar":"لتوضيح الوقت والترتيب.","options":["to make the paragraph funny","to show when things happen and keep them in order","to replace the topic sentence","to add pictures"],"dok":2,"skill":"purpose"},{"q":"Your partner's paragraph starts with *I wake up at six.* What is missing?","answer":"a topic sentence","explanation":"It starts with a detail.","explanation_ar":"الجملة الرئيسية.","options":["a closing","a time word","a detail","a topic sentence"],"dok":3,"skill":"revising"},{"q":"Which busy-day paragraph is the most complete?","answer":"an indent, a topic sentence, details in time order with time words, and/but and a closing","explanation":"It has all the parts.","explanation_ar":"فيه كل الأجزاء.","options":["a list of times with no sentences","one sentence about breakfast","an indent, a topic sentence, details in time order with time words, and/but and a closing","a picture of a clock only"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L02-U6-LS5-V01","prompt":"Picture for the word 'busy': a child juggling a book, a ball and a lunchbox"},{"id":"IMG-RW-L02-U6-LS5-V02","prompt":"Picture for the word 'practice': children training on a football field"},{"id":"IMG-RW-L02-U6-LS5-V03","prompt":"Picture for the word 'homework': a child writing at a desk at home"},{"id":"IMG-RW-L02-U6-LS5-V04","prompt":"Picture for the word 'dinner': a family dinner table"},{"id":"IMG-RW-L02-U6-LS5-V05","prompt":"Picture for the word 'bedtime': a child in bed with a book and a moon outside"},{"id":"IMG-RW-L02-U6-LS5-V06","prompt":"Picture for the word 'tired': a yawning child"},{"id":"IMG-RW-L02-U6-LS5-V07","prompt":"Picture for the word 'schedule': a weekly schedule chart with icons"},{"id":"IMG-RW-L02-U6-LS5-01","prompt":"Omar's busy Tuesday shown around a clock face."},{"id":"IMG-RW-L02-U6-LS5-02","prompt":"A hamburger organizer next to a day line."},{"id":"IMG-RW-L02-U6-LS5-03","prompt":"A classroom wall of clock-shaped paragraphs."}],"audio":[{"id":"AUD-RW-L02-U6-LS5-V01","script":"busy. Tuesday is a busy day."},{"id":"AUD-RW-L02-U6-LS5-V02","script":"practice. I have football practice at four o'clock."},{"id":"AUD-RW-L02-U6-LS5-V03","script":"homework. I do my homework after lunch."},{"id":"AUD-RW-L02-U6-LS5-V04","script":"dinner. We eat dinner at seven o'clock."},{"id":"AUD-RW-L02-U6-LS5-V05","script":"bedtime. My bedtime is nine o'clock."},{"id":"AUD-RW-L02-U6-LS5-V06","script":"tired. I am tired after a busy day."},{"id":"AUD-RW-L02-U6-LS5-V07","script":"schedule. My schedule is on the fridge."},{"id":"AUD-RW-L02-U6-LS5-VID","script":"Omar has a VERY busy Tuesday! Let's help him write about it. Plan: topic sentence on top; details in time order; closing at the bottom. Draft: Tuesday is my busiest day of the week. I wake up at five o'clock for the Fajr prayer… Revise: 'My uncle's car is white.' Does it belong? No! Cross it out. Edit: indent, capitals, at + o'clock, commas before and/but – check! Publish: Omar copies his paragraph inside a big clock and reads it to the class!"}]}],"unit_test":[{"q":"We eat dinner in the ___.","answer":"evening","explanation":"Dinner is in the evening.","explanation_ar":"المساء.","options":["evening","morning","yesterday","week"],"dok":1,"skill":"time words","_part":"Part A – Words"},{"q":"Today is Sunday. ___ was Saturday.","answer":"Yesterday","explanation":"The day before today.","explanation_ar":"أمس.","options":["Tomorrow","Tonight","Today","Yesterday"],"dok":1,"skill":"time words","_part":"Part A – Words"},{"q":"The first ___ of the day is Fajr.","answer":"prayer","explanation":"Fajr is a prayer.","explanation_ar":"صلاة.","options":["clock","week","prayer","bakery"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The bus left at seven, and Faris got there at ten past seven. He was ___.","answer":"late","explanation":"After the time = late.","explanation_ar":"متأخر.","options":["early","late","busy","bold"],"dok":1,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Sami does his homework, football practice and reading on Tuesday. Tuesday is a ___ day.","answer":"busy","explanation":"A lot to do = busy.","explanation_ar":"مزدحم.","options":["silly","ripe","loose","busy"],"dok":1,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"A baker mixes flour and water to make ___.","answer":"dough","explanation":"Dough = flour + water.","explanation_ar":"العجين.","options":["soil","dough","a calendar","a caption"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which phrase about the Isha prayer is correct?","answer":"at night","explanation":"at night.","explanation_ar":"at night.","options":["in night","on night","at night","at the night on"],"dok":2,"skill":"prepositions of time","_part":"Part A – Words"},{"q":"*My **schedule** is on the fridge. It shows what I do every day and when.* *Schedule* means ___.","answer":"a plan of times and activities","explanation":"Clue: shows what I do and when.","explanation_ar":"جدول.","options":["a plan of times and activities","a kind of food","a heading","a sleepy feeling"],"dok":2,"skill":"context clues","_part":"Part A – Words"},{"q":"Details: *I visit Grandpa. I water his palm trees. We eat lunch together.* Best topic sentence?","answer":"Friday at Grandpa's house is special.","explanation":"It covers all the details.","explanation_ar":"تغطي التفاصيل.","options":["I like football.","Friday at Grandpa's house is special.","Palm trees are tall.","Lunch is at one o'clock."],"dok":2,"skill":"topic sentence","_part":"Part D – Check the paragraph"},{"q":"Topic sentence: *My school mornings are busy.* Which detail does NOT belong?","answer":"Sand timers use sand.","explanation":"Not about school mornings.","explanation_ar":"لا تنتمي.","options":["Sand timers use sand.","I wake up at six o'clock.","I eat breakfast quickly.","I catch the bus at seven."],"dok":1,"skill":"relevant details","_part":"Part D – Check the paragraph"},{"q":"In a play, what do the words in brackets tell actors?","answer":"what to do and how to say the line","explanation":"Brackets = stage directions.","explanation_ar":"ماذا يفعلون وكيف يقولون.","options":["the title of the play","the meaning of bold words","what to do and how to say the line","the time of the test"],"dok":1,"skill":"drama features","_part":"Part D – Check the paragraph"},{"q":"Which detail about the school bus uses the time correctly?","answer":"The bus comes at seven o'clock.","explanation":"at + o'clock.","explanation_ar":"صحيحة.","options":["The bus comes in seven o'clock.","The bus comes on seven o'clock.","The bus comes at seven clock.","The bus comes at seven o'clock."],"dok":1,"skill":"prepositions of time","_part":"Part D – Check the paragraph"},{"q":"How should the first line of a paragraph begin?","answer":"with an indent and a topic sentence","explanation":"Indent + topic sentence.","explanation_ar":"مسافة بادئة وجملة رئيسية.","options":["with the closing","with a caption","with an indent and a topic sentence","with a bold heading"],"dok":2,"skill":"paragraph form","_part":"Part D – Check the paragraph"}],"unit_writing":{"task":"Write a paragraph about your weekend. Indent the first line, start with a topic sentence, put the details in time order and end with a closing.","model":"My weekend is calm and happy. On Friday morning, I go to the mosque with my father. In the afternoon, we visit my grandparents, and I play with my cousins. On Saturday, I read a library book and help my mother in the kitchen. In the evening, we eat dinner together. I love my weekend because I spend time with my family.","marks":20}});
